import { TextSelection } from "@tiptap/pm/state"
import type { Editor } from "@tiptap/react"
import { ArrowDownIcon, ArrowUpIcon, ClipboardIcon, CopyIcon, EraserIcon, Link2Icon, PaletteIcon, ReplaceIcon, Trash2Icon } from "@/shared/ui/icon"
import { colorEntries, TEXT_BLOCKS, turnInto, turnIntoEntries, type TextBlockId } from "./format"
import { MOD, type MenuEntry } from "./menu"

const TYPE_LABELS: Record<string, string> = { paragraph: "텍스트", bulletList: "글머리 목록", orderedList: "번호 목록", taskList: "할 일 목록", blockquote: "인용",
  codeBlock: "코드", table: "표", media: "파일", mermaidBlock: "다이어그램", horizontalRule: "구분선", webEmbed: "링크 카드" }
/** 색을 입히거나 종류를 바꿀 수 있는 글 블록. 코드는 색을 입히지 않는다. */
const TEXTUAL = ["paragraph", "heading", "bulletList", "orderedList", "taskList", "blockquote", "codeBlock"]

export type MenuBlock = { id: string; pos: number; size: number; type: string }

/** 그 블록의 주소: 지금 화면 주소에 블록 표시(#block-…)를 붙인다. 그 주소로 열면 그 블록으로 옮겨 간다(RichEditor). */
export const blockLink = (id: string) => `${window.location.origin}${window.location.pathname}${window.location.search}#block-${id}`

/** 블록을 클립보드에 담는다: 붙여 넣을 때 서식이 살도록 HTML과 글을 함께. */
export async function copyBlocks(editor: Editor, ranges: { pos: number; size: number }[]) {
  if (!ranges.length) return
  const from = Math.min(...ranges.map(range => range.pos)), to = Math.max(...ranges.map(range => range.pos + range.size))
  const { dom, text } = editor.view.serializeForClipboard(editor.state.doc.slice(from, to))
  try {
    await navigator.clipboard.write([new ClipboardItem({ "text/html": new Blob([dom.innerHTML], { type: "text/html" }), "text/plain": new Blob([text], { type: "text/plain" }) })])
  } catch { await navigator.clipboard.writeText(text).catch(() => undefined) }
}

/**
 * 블록 손잡이를 누르면 뜨는 메뉴의 항목. 위에는 블록의 종류, 그 아래로 색(글자색 · 배경색)과 종류 바꾸기(하위 메뉴), 서식 지우기,
 * 복제 · 복사 · 링크 복사, 위 · 아래로 옮기기, 삭제가 묶음별로 놓인다. 단축키는 블록을 고른 채 누르면 동작한다(RichEditor의 keys).
 */
export function blockMenuEntries({ editor, block, atomic, onStep }: {
  editor: Editor; block: MenuBlock; atomic: (fn: () => unknown) => void; onStep: (direction: number) => void
}): MenuEntry[] {
  const node = editor.state.doc.nodeAt(block.pos)
  const isTextual = TEXTUAL.includes(block.type), canColor = isTextual && block.type !== "codeBlock"
  const title = block.type === "heading" ? `제목 ${node?.attrs.level ?? ""}` : TYPE_LABELS[block.type] ?? "블록"
  // 지금 입혀진 색: 블록의 첫 글자에 있는 것으로 본다.
  let ink = "", fill = ""
  node?.descendants(child => {
    if (!child.isText) return true
    for (const mark of child.marks) { if (mark.type.name === "textStyle") ink = mark.attrs.color ?? ""; if (mark.type.name === "highlight") fill = mark.attrs.color ?? "" }
    return false
  })
  const current: TextBlockId | undefined = block.type === "heading" ? `heading${node?.attrs.level}` as TextBlockId : TEXT_BLOCKS.find(each => each.id === block.type)?.id
  /** 블록의 글 전체를 고른 채 명령을 돌리고, 커서를 블록 끝에 둔다(서식 도구가 따라 뜨지 않게). 한 번의 실행 취소 단위다. */
  const onBlock = (fn: () => unknown) => () => atomic(() => {
    const { doc, tr } = editor.state
    const from = TextSelection.near(doc.resolve(block.pos + 1), 1).from, to = TextSelection.near(doc.resolve(block.pos + block.size - 1), -1).to
    editor.view.dispatch(tr.setSelection(TextSelection.create(doc, from, Math.max(from, to))))
    fn()
    const after = editor.state
    editor.view.dispatch(after.tr.setSelection(TextSelection.near(after.doc.resolve(after.selection.to), -1)))
  })
  const chain = () => editor.chain().focus()
  const duplicate = () => { if (node) atomic(() => chain().insertContentAt(block.pos + block.size, node.toJSON()).run()) }
  const remove = () => atomic(() => chain().deleteRange({ from: block.pos, to: block.pos + block.size }).run())
  return [
    { kind: "title", label: title },
    { kind: "sub", label: "색", icon: <PaletteIcon />, isDisabled: !canColor, entries: colorEntries(ink, fill,
      color => onBlock(() => color ? chain().setColor(color).run() : chain().unsetColor().run())(),
      color => onBlock(() => color ? chain().setHighlight({ color }).run() : chain().unsetHighlight().run())()) },
    { kind: "sub", label: "종류 바꾸기", icon: <ReplaceIcon />, isDisabled: !isTextual, entries: turnIntoEntries(current, id => onBlock(() => turnInto(editor, id))()) },
    { kind: "item", label: "서식 지우기", icon: <EraserIcon />, isDisabled: !canColor, onSelect: onBlock(() => chain().unsetAllMarks().run()) },
    { kind: "separator" },
    { kind: "item", label: "복제", icon: <CopyIcon />, hint: `${MOD} D`, onSelect: duplicate },
    { kind: "item", label: "복사", icon: <ClipboardIcon />, hint: `${MOD} C`, onSelect: () => void copyBlocks(editor, [block]) },
    { kind: "item", label: "링크 복사", icon: <Link2Icon />, onSelect: () => void navigator.clipboard.writeText(blockLink(block.id)).catch(() => undefined) },
    { kind: "separator" },
    { kind: "item", label: "위로 옮기기", icon: <ArrowUpIcon />, hint: "Alt ↑", onSelect: () => onStep(-1) },
    { kind: "item", label: "아래로 옮기기", icon: <ArrowDownIcon />, hint: "Alt ↓", onSelect: () => onStep(1) },
    { kind: "separator" },
    { kind: "item", label: "삭제", icon: <Trash2Icon />, hint: "Del", isDanger: true, onSelect: remove },
  ]
}

import { useEffect, useReducer, useState, type ReactNode } from "react"
import {
  BoldIcon, ChevronDownIcon, CodeIcon, EraserIcon, ItalicIcon, Link2Icon, ListChecksIcon, ListIcon, ListOrderedIcon, PlusIcon, Redo2Icon,
  StrikethroughIcon, UnderlineIcon, Undo2Icon,
} from "@/shared/ui/icon"
import { ALIGN_LABELS, AlignGlyph, Swatch, TEXT_BLOCKS, colorEntries, textBlockOf, turnInto, turnIntoEntries, type Align } from "./format"
import { LinkPanel } from "./LinkPanel"
import { EditorMenu, EditorPopover, keepSelection, MOD, type MenuEntry } from "./menu"
import type { EditorHandle } from "./RichEditor"
import { COMMAND_ICONS, COMMANDS, type CommandId } from "./schema"
import { setFill, setInk } from "./SelectionMenu"
import { ToolButton, ToolDivider } from "./tool"
import type { LinkChoice } from "./types"

type Panel = "type" | "color" | "link" | "align" | "insert"

/** 넣기 메뉴의 블록: `/` 명령(COMMANDS)과 같은 이름 · 아이콘을 쓴다. 글 블록 종류는 블록 종류 메뉴가 맡는다. */
const INSERT_IDS: CommandId[] = ["table", "file", "codeBlock", "mermaidBlock", "blockquote", "horizontalRule"]

/** 에디터가 바뀔 때마다(선택 · 입력) 다시 그려 눌림 상태를 맞춘다. */
function useEditorTick(handle: EditorHandle | null) {
  const [, tick] = useReducer((value: number) => value + 1, 0)
  useEffect(() => {
    const editor = handle?.editor
    if (!editor) return undefined
    editor.on("transaction", tick)
    return () => { editor.off("transaction", tick) }
  }, [handle?.editor])
}

/**
 * 상단 서식 막대. 문서 편집기처럼 본문 위에 늘 붙어 있는 도구 줄이며, 글을 고르지 않아도 지금 커서 자리의 서식이 보인다.
 * 왼쪽부터 (start), 되돌리기, 블록 종류, 글자 서식, 색 · 링크, 정렬, 목록, 넣기 메뉴(표 · 파일 · 코드 · 도표 · 인용 · 구분선), 서식 지우기.
 * 위 · 아래 첨자와 들여쓰기 · 내어쓰기는 글을 고르면 뜨는 서식 도구의 더 보기와 Tab · Shift+Tab에 있다(막대를 한 줄로 두려고 뺐다).
 * 넣기는 `/` 명령과 같은 방식이라 파일은 올리는 칸이 뜬다. 좁으면 줄을 바꾼다(가로로 밀면 메뉴를 여닫을 때 스크롤바가 생겼다
 * 사라지며 막대가 흔들린다). 휴대폰은 도구가 44px라 줄을 바꾸면 화면을 덮으므로 한 줄에서 가로로 민다(메뉴는 바텀시트라 흔들리지 않는다).
 * 오른쪽 끝(end)은 늘 첫 줄 끝에 있다. 핸들이 없으면(에디터 준비 전) 흐리게 그린다.
 */
export function EditorToolbar({ handle, links, start, end }: { handle: EditorHandle | null; links?: LinkChoice[]; start?: ReactNode; end?: ReactNode }) {
  useEditorTick(handle)
  const [open, setOpen] = useState<Panel | null>(null)
  const editor = handle?.editor ?? null
  const isReady = !!editor && editor.isEditable
  const chain = () => editor!.chain().focus()
  const active = (name: string) => !!editor?.isActive(name)
  const toggle = (panel: Panel) => (next: boolean) => setOpen(next ? panel : null)
  const tool = (label: string, drawing: ReactNode, run: () => unknown, options: { isActive?: boolean; isDisabled?: boolean; shortcut?: string } = {}) =>
    <ToolButton label={label} tip={options.shortcut ? `${label} (${options.shortcut})` : label} aria-pressed={options.isActive ?? undefined}
      disabled={!isReady || options.isDisabled} onMouseDown={keepSelection} onClick={() => run()}>{drawing}</ToolButton>
  const type = editor ? textBlockOf(editor) : "paragraph"
  const ink = String(editor?.getAttributes("textStyle").color ?? ""), fill = String(editor?.getAttributes("highlight").color ?? "")
  const align = (editor?.getAttributes("paragraph").textAlign ?? editor?.getAttributes("heading").textAlign ?? "left") as Align
  const inserts: MenuEntry[] = INSERT_IDS.map(id => {
    const Icon = COMMAND_ICONS[id]
    return { kind: "item", label: COMMANDS.find(command => command.id === id)!.label, icon: <Icon />, onSelect: () => handle?.insert(id) }
  })
  return (
    <div className="box-border flex min-h-11 w-full items-start gap-2 border-b bg-background px-3 py-1.5 max-md:items-center max-md:px-1">
      <div role="toolbar" aria-label="서식" className="flex min-h-8 min-w-0 flex-auto flex-wrap items-center gap-x-0.5 gap-y-1 max-md:flex-nowrap max-md:overflow-x-auto max-md:[scrollbar-width:none]">
        {start ? <>{start}<ToolDivider /></> : null}
        {tool("되돌리기", <Undo2Icon />, () => chain().undo().run(), { isDisabled: !editor?.can().undo(), shortcut: `${MOD}+Z` })}
        {tool("다시 하기", <Redo2Icon />, () => chain().redo().run(), { isDisabled: !editor?.can().redo(), shortcut: `${MOD}+Shift+Z` })}
        <ToolDivider />
        <EditorMenu label="블록 종류" open={open === "type"} onOpenChange={toggle("type")}
          entries={editor ? turnIntoEntries(type, id => turnInto(editor, id)) : []}
          trigger={<ToolButton label="블록 종류" isWide disabled={!isReady} className="min-w-22 justify-between">
            {TEXT_BLOCKS.find(block => block.id === type)?.label ?? "텍스트"}<ChevronDownIcon />
          </ToolButton>} />
        <ToolDivider />
        {tool("굵게", <BoldIcon />, () => chain().toggleBold().run(), { isActive: active("bold"), shortcut: `${MOD}+B` })}
        {tool("기울임", <ItalicIcon />, () => chain().toggleItalic().run(), { isActive: active("italic"), shortcut: `${MOD}+I` })}
        {tool("밑줄", <UnderlineIcon />, () => chain().toggleUnderline().run(), { isActive: active("underline"), shortcut: `${MOD}+U` })}
        {tool("취소선", <StrikethroughIcon />, () => chain().toggleStrike().run(), { isActive: active("strike") })}
        {tool("인라인 코드", <CodeIcon />, () => chain().toggleCode().run(), { isActive: active("code") })}
        <ToolDivider />
        <EditorMenu label="색" open={open === "color"} onOpenChange={toggle("color")}
          entries={editor ? colorEntries(ink, fill, color => setInk(editor, color), color => setFill(editor, color)) : []}
          trigger={<ToolButton label="색" isWide disabled={!isReady}><Swatch ink={ink || undefined} fill={fill || undefined} isFramed /><ChevronDownIcon /></ToolButton>} />
        <EditorPopover label="링크" open={open === "link" && !!editor} onOpenChange={toggle("link")}
          trigger={<ToolButton label="링크" tip={`링크 (${MOD}+K)`} aria-pressed={active("link")}
            disabled={!isReady || (editor?.state.selection.empty && !active("link"))}><Link2Icon /></ToolButton>}>
          {editor ? <LinkPanel editor={editor} links={links} onDone={() => setOpen(null)} /> : null}
        </EditorPopover>
        <ToolDivider />
        <EditorMenu label="정렬" open={open === "align"} onOpenChange={toggle("align")}
          entries={(["left", "center", "right", "justify"] as const).map(kind => ({ kind: "item", label: ALIGN_LABELS[kind], icon: <AlignGlyph kind={kind} />,
            isChecked: align === kind, onSelect: () => chain().setTextAlign(kind).run() }))}
          className="w-44"
          trigger={<ToolButton label="정렬" tip={ALIGN_LABELS[align]} isWide disabled={!isReady}><AlignGlyph kind={align} /><ChevronDownIcon /></ToolButton>} />
        {tool("글머리 기호 목록", <ListIcon />, () => chain().toggleBulletList().run(), { isActive: active("bulletList") })}
        {tool("번호 매기기 목록", <ListOrderedIcon />, () => chain().toggleOrderedList().run(), { isActive: active("orderedList") })}
        {tool("할 일 목록", <ListChecksIcon />, () => chain().toggleTaskList().run(), { isActive: active("taskList") })}
        <ToolDivider />
        <EditorMenu label="넣기" open={open === "insert"} onOpenChange={toggle("insert")} entries={inserts}
          trigger={<ToolButton label="넣기" tip="넣기 (표 · 이미지 · 코드 · 도표 · 인용 · 구분선)" isWide disabled={!isReady}><PlusIcon /><ChevronDownIcon /></ToolButton>} />
        <ToolDivider />
        {tool("서식 지우기", <EraserIcon />, () => chain().unsetAllMarks().run())}
      </div>
      {end ? (
        <div className="flex min-h-8 flex-none items-center gap-2 before:mr-2 before:ml-1 before:h-4.5 before:w-px before:flex-none before:bg-border">{end}</div>
      ) : null}
    </div>
  )
}

import { useEffect, useState } from "react"
import { GlobeIcon, ImageIcon, PencilIcon, SquareArrowOutUpRightIcon } from "@/shared/ui/icon"
import { BlockTool, BlockTools } from "./MediaView"
import type { LinkPreview } from "./types"
import { previewOf, useEditorHost } from "./zoom"

/**
 * 링크 카드: 웹 주소 하나를 제목 · 설명 · 대표 사진이 있는 카드로 보여 준다. 미리보기는 호스트의 함수가 읽고(서버가 읽어야 한다),
 * 읽지 못하면 주소만 있는 카드가 된다. 읽는 화면에서는 카드 전체가 새 탭으로 여는 링크이고, 고치는 화면에서는 누르면 블록이
 * 선택되며 열기 · 주소 고치기는 위에 뜨는 도구로 한다. 카드 전체를 덮는 링크와 사진은 키트 부품에 맞는 것이 없어 <a> · <img>로 둔다.
 */
export function LinkCard({ url, host, isEditable, onEdit }: { url: string; host: string; isEditable: boolean; onEdit: () => void }) {
  const { readPreview } = useEditorHost()
  const [preview, setPreview] = useState<LinkPreview | null>(null), [noPicture, setNoPicture] = useState(false)
  useEffect(() => {
    let live = true
    setPreview(null); setNoPicture(false)
    if (!readPreview) { setPreview({ url, site: host }); return }
    previewOf(readPreview, url).then(found => { if (live) setPreview(found) }).catch(() => { if (live) setPreview({ url, site: host }) })
    return () => { live = false }
  }, [url, host, readPreview])
  const title = preview?.title || host, site = preview?.site || host
  return (
    <div className="group/block relative">
      {isEditable ? (
        <BlockTools>
          <BlockTool label="새 탭에서 열기" nativeButton={false} render={<a href={url} target="_blank" rel="noopener noreferrer" />}><SquareArrowOutUpRightIcon /></BlockTool>
          <BlockTool label="링크 카드 주소 고치기" tip="주소 고치기" onClick={onEdit}><PencilIcon /></BlockTool>
        </BlockTools>
      ) : null}
      <a href={url} target="_blank" rel="noopener noreferrer" data-loading={preview ? undefined : ""} draggable={false}
        className="group/card flex min-h-26 items-stretch overflow-hidden rounded-[0.625rem] border bg-card text-foreground no-underline! transition-colors hover:border-input hover:bg-row-hover focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring in-data-selected:border-ring"
        onClick={event => { if (isEditable) event.preventDefault() }}>
        <div className="flex min-w-0 flex-1 flex-col justify-center gap-1 px-3.5 py-3">
          <span className="truncate text-sm leading-snug font-semibold group-data-loading/card:text-muted-foreground">{preview ? title : host}</span>
          {preview?.description ? <span className="line-clamp-2 text-[0.78125rem] leading-normal text-muted-foreground">{preview.description}</span> : null}
          <span className="mt-0.5 flex min-w-0 items-center gap-1.5 text-xs text-muted-foreground [&_svg]:size-3.25 [&_svg]:flex-none">
            <GlobeIcon /><span className="truncate">{site}</span>
            {site !== host ? <span className="truncate opacity-70">{host}</span> : null}
          </span>
        </div>
        {/* 사진 칸은 늘 둔다: 페이지가 대표 사진을 밝히지 않았거나 받지 못하면 같은 자리에 빈 칸 표시를 둬 카드 모양을 맞춘다. */}
        {preview?.image && !noPicture ? (
          <div className="w-[min(34%,14rem)] flex-none border-l bg-muted max-[34.375rem]:w-22">
            <img src={preview.image} alt="" loading="lazy" decoding="async" referrerPolicy="no-referrer" draggable={false} onError={() => setNoPicture(true)}
              className="m-0! block size-full max-w-none rounded-none! object-cover" />
          </div>
        ) : (
          <div className="flex w-[min(34%,14rem)] flex-none flex-col items-center justify-center gap-1.5 border-l bg-muted p-2.5 text-center text-xs text-muted-foreground max-[34.375rem]:w-22 [&_svg]:size-5 [&_svg]:opacity-85">
            <ImageIcon /><span>{preview ? "대표 이미지가 없습니다" : "불러오는 중…"}</span>
          </div>
        )}
      </a>
    </div>
  )
}

import type { Editor } from "@tiptap/react"
import { useState } from "react"
import { Button } from "@/shared/ui/button"
import { FileTextIcon, Link2Icon, SquareArrowOutUpRightIcon, Trash2Icon } from "@/shared/ui/icon"
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/shared/ui/input-group"
import type { LinkChoice } from "./types"

/** 주소로 쓸 수 있게 다듬는다: 앱 안의 주소(/…)와 https · http · mailto는 그대로, 점이 든 낱말(example.com)은 https://를 붙인다. 그 밖은 빈 글. */
export function hrefOf(text: string): string {
  const value = text.trim()
  if (/^(https?:\/\/|mailto:)/i.test(value) || /^\/(?!\/)/.test(value)) return value
  return /^[^\s/]+\.[^\s]{2,}$/.test(value) ? `https://${value}` : ""
}

const ROW = "h-auto min-h-8 w-full justify-start gap-2.5 rounded-md px-2.5 py-1.5 font-normal [&_svg]:text-icon-muted max-md:min-h-12"

/**
 * 링크 입력 칸: 주소를 붙여 넣거나, 문서 이름을 쳐서 호스트가 넘긴 문서(links)를 골라 건다. Enter는 주소면 그 주소로,
 * 아니면 맨 위 문서로 건다. 이미 링크가 걸린 글이면 열기와 지우기가 함께 보인다. 판(EditorPopover) 안에 둔다.
 */
export function LinkPanel({ editor, links, onDone }: { editor: Editor; links?: LinkChoice[]; onDone: () => void }) {
  const current = String(editor.getAttributes("link").href ?? "")
  const [text, setText] = useState(current)
  const href = hrefOf(text), word = text.trim().toLowerCase()
  const found = !href && word && links ? links.filter(link => link.title.toLowerCase().includes(word)).slice(0, 7) : !text.trim() && links ? links.slice(0, 5) : []
  const apply = (target: string) => { editor.chain().focus().extendMarkRange("link").setLink({ href: target }).run(); onDone() }
  const submit = () => { if (href) apply(href); else if (found[0]) apply(found[0].href) }
  return (
    <>
      <div className="flex items-center gap-1">
        <InputGroup className="h-9 border-transparent has-[[data-slot=input-group-control]:focus-visible]:ring-0 max-md:h-11">
          <InputGroupAddon><Link2Icon /></InputGroupAddon>
          <InputGroupInput aria-label="링크 주소 또는 문서 이름" autoFocus value={text}
            placeholder={links ? "주소를 붙여 넣거나 문서 이름으로 찾기" : "주소를 붙여 넣기 (https://…)"}
            onChange={event => setText(event.target.value)}
            onKeyDown={event => { if (event.key === "Enter" && !event.nativeEvent.isComposing) { event.preventDefault(); event.stopPropagation(); submit() } }} />
        </InputGroup>
        {current ? <>
          <Button variant="ghost" size="icon-sm" aria-label="링크 열기" title="링크 열기" className="max-md:size-11"
            render={<a href={current} target="_blank" rel="noopener noreferrer" />} nativeButton={false}><SquareArrowOutUpRightIcon /></Button>
          <Button variant="ghost" size="icon-sm" aria-label="링크 지우기" title="링크 지우기" className="max-md:size-11"
            onClick={() => { editor.chain().focus().extendMarkRange("link").unsetLink().run(); onDone() }}><Trash2Icon /></Button>
        </> : null}
      </div>
      {href && href !== current ? (
        <Button variant="ghost" className={ROW} onClick={() => apply(href)}>
          <Link2Icon /><span className="min-w-0 flex-1 truncate text-left">{href} 로 연결</span><span className="text-xs text-muted-foreground">Enter</span>
        </Button>
      ) : null}
      {found.length > 0 ? <>
        <div className="px-2.5 pt-2 pb-1 text-xs font-semibold text-muted-foreground">문서</div>
        {found.map(link => (
          <Button key={link.href} variant="ghost" className={ROW} onClick={() => apply(link.href)}>
            <FileTextIcon /><span className="min-w-0 flex-1 truncate text-left">{link.title}</span>
            {link.hint ? <span className="max-w-32 truncate text-xs text-muted-foreground">{link.hint}</span> : null}
          </Button>
        ))}
      </> : null}
      {!href && word && !found.length
        ? <p className="px-2.5 py-2 text-xs text-muted-foreground">{links ? "찾은 문서가 없습니다. 주소는 https://로 시작해 주세요." : "https:// 또는 mailto:로 시작하는 주소를 넣어 주세요."}</p>
        : null}
    </>
  )
}

import type { Editor } from "@tiptap/core"
import { closeHistory } from "@tiptap/pm/history"
import { NodeViewWrapper, ReactNodeViewRenderer, type NodeViewProps } from "@tiptap/react"
import { useEffect, useLayoutEffect, useRef, useState, type ComponentProps, type CSSProperties, type ReactNode } from "react"
import { cn } from "@/shared/lib/utils"
import { Button } from "@/shared/ui/button"
import { CheckIcon, ChevronDownIcon, CopyIcon, DownloadIcon, FileTextIcon, OctagonXIcon, RefreshCwIcon, ZoomInIcon } from "@/shared/ui/icon"
import { bytes, clampWidth, FILE_TONE_CLASS, fileKind } from "./file-kinds"
import { EditorMenu } from "./menu"
import { Media, safeSource } from "./schema"
import { Tip } from "./tool"
import { HTML_SANDBOX, useEditorHost } from "./zoom"

/** 노드 뷰 안에서 지금 편집할 수 있는지. 읽기 · 편집을 오가도 노드 뷰는 다시 만들어지지 않는다. */
export function useEditable(editor: Editor) {
  const [isEditable, setEditable] = useState(editor.isEditable)
  useEffect(() => {
    const update = () => setEditable(editor.isEditable)
    editor.on("transaction", update); editor.on("update", update); update()
    return () => { editor.off("transaction", update); editor.off("update", update) }
  }, [editor])
  return isEditable
}

/**
 * 블록 위에 떠 있는 도구 띠: 포인터를 올리거나 초점이 들어오면 블록 오른쪽 위에 뜬다(머리 띠를 두지 않는다). 터치 화면은 늘 보인다.
 * 부모에 group/block을 단다. isStatic이면 제자리(파일 카드 안 · 오디오 아래)에 늘 보인다.
 */
export function BlockTools({ isStatic = false, children }: { isStatic?: boolean; children: ReactNode }) {
  return (
    <div className={cn("z-2 flex items-center gap-0.5 print:hidden",
      isStatic ? "" : "absolute top-2 right-2 rounded-[0.5625rem] border border-input bg-popover p-0.5 shadow-md opacity-0 transition-opacity group-hover/block:opacity-100 group-focus-within/block:opacity-100 pointer-coarse:opacity-100 motion-reduce:transition-none")}>
      {children}
    </div>
  )
}

/** 도구 띠의 아이콘 단추. 휴대폰은 44px. */
export function BlockTool({ label, tip = label, children, ...props }: { label: string; tip?: string; children: ReactNode } & Omit<ComponentProps<typeof Button>, "children">) {
  return <Tip label={tip}><Button variant="ghost" size="icon-sm" aria-label={label} className="text-icon-muted hover:text-foreground max-md:size-11" {...props}>{children}</Button></Tip>
}

/** 원문을 복사하는 도구. 결과는 잠시 아이콘과 상태 문구로 알린다. */
export function CopyButton({ text, label }: { text: string; label: string }) {
  const [state, setState] = useState<"idle" | "copied" | "error">("idle")
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  useEffect(() => () => clearTimeout(timer.current), [])
  return (
    <BlockTool label={label} tip={state === "copied" ? "복사됨" : state === "error" ? "복사하지 못했습니다" : label}
      onClick={async () => {
        try { await navigator.clipboard.writeText(text); setState("copied") } catch { setState("error") }
        clearTimeout(timer.current); timer.current = setTimeout(() => setState("idle"), 1800)
      }}>
      {state === "copied" ? <CheckIcon /> : state === "error" ? <OctagonXIcon /> : <CopyIcon />}
    </BlockTool>
  )
}

/** 이미 받은 사진: 다시 나오면 바로 보인다(서서히 나타나지 않는다). */
const arrived = new Set<string>()
const isAtHand = (src: string) => {
  if (!src) return false
  if (arrived.has(src)) return true
  const probe = new Image()
  probe.src = src
  return probe.complete && probe.naturalWidth > 0
}

const LABELS = { image: "이미지", video: "동영상", audio: "오디오", file: "파일" } as const
const WIDTHS = [25, 50, 75, 100]

/** 사진 · 동영상의 너비 고르기(25 · 50 · 75 · 100%, 옛 본문의 다른 값은 그 값도 보인다). */
function WidthMenu({ width, onChange }: { width: number; onChange: (value: number) => void }) {
  const [isOpen, setOpen] = useState(false)
  return (
    <EditorMenu label="미디어 너비" open={isOpen} onOpenChange={setOpen} align="end" className="w-32"
      entries={[...(!WIDTHS.includes(width) ? [width] : []), ...WIDTHS].map(value => ({ kind: "item", label: `${value}%`, isChecked: value === width, onSelect: () => onChange(value) }))}
      trigger={<Tip label="미디어 너비"><Button variant="ghost" size="sm" aria-label={`미디어 너비 ${width}%`} className="gap-0.5 px-1.5 text-xs max-md:h-11">{width}%<ChevronDownIcon /></Button></Tip>} />
  )
}

/**
 * 사진 · 동영상 · 오디오 · 파일 블록. 머리 띠 · 상자 틀 · 사진 아래 이름 줄이 없다. 도구(크게 보기 · 너비 · 내려받기)는 포인터를 올리거나
 * 초점이 들어오면 블록 오른쪽 위에 뜬다. 사진은 올릴 때 잰 원본 비율로 자리를 먼저 잡고 대표색으로 칠한 뒤 나타나며, 너비를
 * 25% · 50%로 줄인 사진끼리는 한 줄에 나란히 놓인다(prose의 규칙). 파일은 확장자의 색을 띤 카드로, HTML 파일은 그 아래 격리된 미리보기 틀로 보인다.
 * 사진 · 영상 · 격리 틀은 키트 부품이 없어 <img> · <video> · <audio> · <iframe>을 그대로 쓰고, 비율 · 대표색 · 너비는 블록마다 달라 인라인으로 준다.
 */
function MediaView({ node, editor, updateAttributes, getPos, selected }: NodeViewProps) {
  const isEditable = useEditable(editor), { openZoom, openHtml } = useEditorHost(), a = node.attrs
  const mime = String(a.mime), name = String(a.name)
  const kind = mime.startsWith("image/") ? "image" : mime.startsWith("video/") ? "video" : mime.startsWith("audio/") ? "audio" : "file"
  const safe = safeSource(a.src), width = clampWidth(a.width), label = LABELS[kind]
  const [state, setState] = useState<"loading" | "ready" | "error">("loading"), [retry, setRetry] = useState(0), [size, setSize] = useState(Number(a.size) || 0)
  const stage = useRef<HTMLDivElement>(null), picture = useRef<HTMLImageElement>(null), [isNearby, setNearby] = useState(false)
  const src = retry && !safe.startsWith("blob:") ? `${safe}${safe.includes("?") ? "&" : "?"}retry=${retry}` : safe
  // 올릴 때 잰 대표색과 원본 비율이 있으면 자리를 먼저 그 색 · 비율로 칠하고, 받아야 하는 사진만 서서히 나타낸다(이미 받은 사진은 바로).
  const color = kind === "image" && typeof a.color === "string" && /^#[0-9a-fA-F]{6}$/.test(a.color) ? a.color : undefined
  const ratio = kind === "image" && Number(a.pixelWidth) > 0 && Number(a.pixelHeight) > 0 ? `${a.pixelWidth} / ${a.pixelHeight}` : undefined
  const [atHand] = useState(() => isAtHand(safe))
  useLayoutEffect(() => {
    setState("loading")
    if (!safe) { setState("error"); return }
    if (kind !== "file") return
    if (safe.startsWith("blob:")) { setSize(Number(a.size) || 0); setState("ready"); return }
    const controller = new AbortController()
    void fetch(src, { method: "HEAD", signal: controller.signal })
      .then(response => { if (!response.ok) throw Error(); setSize(Number(response.headers.get("content-length")) || Number(a.size) || 0); setState("ready") })
      .catch(error => { if (error.name !== "AbortError") setState("error") })
    return () => controller.abort()
  }, [src, kind, safe])
  useEffect(() => {
    if (!stage.current) return
    const observer = new IntersectionObserver(entries => { if (entries.some(entry => entry.isIntersecting)) setNearby(true) }, { rootMargin: "300px" })
    observer.observe(stage.current)
    return () => observer.disconnect()
  }, [kind])
  useEffect(() => {
    if (state !== "loading" || (kind !== "file" && !isNearby)) return
    const timer = setTimeout(() => setState("error"), 15000)
    return () => clearTimeout(timer)
  }, [state, retry, isNearby, kind])
  const changeWidth = (value: number) => {
    editor.view.dispatch(closeHistory(editor.state.tr))
    updateAttributes({ width: value })
    editor.view.dispatch(closeHistory(editor.state.tr))
    const pos = getPos()
    if (typeof pos === "number") editor.chain().focus().setNodeSelection(pos).run()
  }
  const status = state === "loading" && color ? null
    : state === "error" ? (
      <div role="alert" className={cn("flex min-h-24 flex-col items-center justify-center gap-2 p-6 text-center text-muted-foreground", kind !== "file" && "absolute inset-0")}>
        <OctagonXIcon className="text-destructive" /><span className="text-sm font-medium text-foreground">{label}를 불러오지 못했습니다</span>
        <span className="text-xs">연결이나 파일 상태를 확인해 주세요.</span>
        <Button variant="secondary" size="sm" className="max-md:h-11" onClick={() => setRetry(n => n + 1)}><RefreshCwIcon data-icon="inline-start" />다시 시도</Button>
      </div>
    ) : state === "loading" ? (
      <div role="status" className={cn("pointer-events-none flex min-h-24 items-center justify-center gap-2 bg-muted p-6 text-xs text-muted-foreground", kind !== "file" && "absolute inset-0")}>
        <RefreshCwIcon className="animate-spin motion-reduce:animate-none" />{label} 불러오는 중…
      </div>
    ) : null
  const zoom = () => {
    const image = picture.current
    if (image) openZoom({ src: image.currentSrc || src, alt: name, width: Number(a.pixelWidth) || image.naturalWidth || undefined, height: Number(a.pixelHeight) || image.naturalHeight || undefined })
  }
  const file = fileKind(name)
  // HTML 파일은 카드 아래에 미리보기를 둔다. 올린 사람의 스크립트가 들어 있을 수 있으므로 격리된 틀(sandbox, 같은 출처 권한 없음)
  // 안에서만 그린다: 틀 안의 문서는 이 앱의 화면 · 쿠키 · 저장소에 닿지 못한다.
  const isHtml = kind === "file" && (mime === "text/html" || /\.html?$/i.test(name))
  const tools = (
    <BlockTools isStatic={kind === "file" || kind === "audio"}>
      {kind === "image" && state === "ready" ? <BlockTool label={`${name} 크게 보기`} tip="크게 보기" onClick={zoom}><ZoomInIcon /></BlockTool> : null}
      {isHtml && safe && state !== "error" ? <BlockTool label={`${name} 크게 보기`} tip="크게 보기" onClick={() => openHtml({ src, title: name })}><ZoomInIcon /></BlockTool> : null}
      {isEditable && (kind === "image" || kind === "video") ? <WidthMenu width={width} onChange={changeWidth} /> : null}
      <BlockTool label={`${name} 다운로드`} tip="다운로드" nativeButton={false} render={<a href={safe || undefined} download={name} />}><DownloadIcon /></BlockTool>
    </BlockTools>
  )
  // 사진의 자리: 원본 비율을 알면 그 비율로, 너무 긴 사진은 높이 한도(32rem)에 맞춘 폭으로 잡아 가운데에 둔다.
  const box: CSSProperties | undefined = kind === "image" && ratio && state !== "error"
    ? { aspectRatio: ratio, inlineSize: `min(100%, calc(32rem * ${a.pixelWidth} / ${a.pixelHeight}))`, backgroundColor: state === "ready" ? undefined : color }
    : state === "error" ? undefined : { backgroundColor: color }
  return (
    <NodeViewWrapper as="figure" data-kind={kind} data-html={isHtml ? "" : undefined} data-selected={selected && isEditable ? "" : undefined}
      data-media="" data-width={width} data-block-id={a.blockId} data-media-state={state} contentEditable={false}
      className={cn("group/block relative mx-auto my-(--block-gap) rounded-[0.625rem] p-0 data-selected:outline-2 data-selected:outline-offset-4 data-selected:outline-ring",
        kind === "file" && "mx-0 max-w-md", isHtml && "max-w-none")}
      // check-ui: allow-style 사진 · 동영상의 너비는 블록마다 고른 값이다.
      style={kind === "image" || kind === "video" ? { width: `${width}%` } : undefined}>
      {kind === "file" ? (
        <div className={cn("relative flex items-center gap-3 border bg-card px-3 py-2.5 transition-colors hover:bg-row-hover", isHtml ? "rounded-t-xl" : "rounded-xl")}>
          <div aria-hidden className={cn("flex h-12 w-11 flex-none flex-col items-center justify-center gap-px rounded-[0.5625rem] [&_svg]:size-4.5", FILE_TONE_CLASS[file.tone])}>
            <FileTextIcon /><span className="text-[0.5625rem] leading-none font-bold tracking-wider">{file.label}</span>
          </div>
          <div className="flex min-w-0 flex-1 flex-col gap-0.5">
            <span className="truncate text-sm font-semibold">{name}</span>
            <span className="text-xs text-muted-foreground">{[file.name, bytes(size)].filter(Boolean).join(" · ")}</span>
          </div>
          {tools}
        </div>
      ) : (
        <div ref={stage} data-state={state} data-ratio={ratio ? "" : undefined}
          className={cn("relative mx-auto overflow-hidden rounded-[0.625rem]", kind === "image" && "w-fit max-w-full", kind === "audio" && "overflow-visible")}
          // check-ui: allow-style 원본 비율과 대표색은 사진마다 다르다.
          style={box}>
          {safe && kind === "image" ? <img ref={picture} key={src} src={src} alt={name} loading="lazy" data-zoomable={!isEditable ? "" : undefined}
            className={cn("block size-full max-h-[32rem] rounded-[0.625rem] object-contain data-zoomable:cursor-zoom-in", !ratio && "w-auto max-w-full",
              color && !atHand && "animate-in fade-in duration-300 motion-reduce:animate-none")}
            // 읽기 화면에서 누르면 크게 보기로 연다(편집 중에는 누르기가 선택이라 두지 않는다).
            onClick={isEditable ? undefined : zoom} onLoad={() => { arrived.add(src); setState("ready") }} onError={() => setState("error")} /> : null}
          {safe && kind === "video" ? <video key={src} src={src} controls preload="metadata" aria-label={name} className="block max-h-[32rem] w-full rounded-[0.625rem] bg-foreground"
            onLoadedMetadata={() => setState("ready")} onError={() => setState("error")}
            onWaiting={() => setState(previous => previous === "error" ? previous : "loading")} onCanPlay={() => setState("ready")} /> : null}
          {safe && kind === "audio" ? <audio key={src} src={src} controls preload="metadata" aria-label={name} className="block w-full"
            onLoadedMetadata={() => setState("ready")} onError={() => setState("error")} /> : null}
          {status}
          {kind === "audio" ? <div className="mt-1.5 flex justify-end">{tools}</div> : tools}
        </div>
      )}
      {isHtml && safe && state !== "error" ? <iframe src={src} title={`${name} 미리보기`} sandbox={HTML_SANDBOX} referrerPolicy="no-referrer" loading="lazy"
        className="block h-104 min-h-40 w-full resize-y rounded-b-xl border border-t-0 bg-white [color-scheme:light] print:hidden" /> : null}
      {kind === "file" ? status : null}
    </NodeViewWrapper>
  )
}

export const MediaNodeView = Media.extend({ addNodeView() { return ReactNodeViewRenderer(MediaView) } })

import type { JSONContent } from "@tiptap/react"
import { useRef } from "react"
import { RichEditor } from "./RichEditor"
import type { ReadLinkPreview } from "./types"

/**
 * 읽는 본문: 작성할 때의 스키마 그대로 읽는다. 사진 · 도표는 눌러 크게 보고, 링크 카드는 카드 전체가 새 탭 링크다. 앱 안의 주소로
 * 가는 링크(문서 언급)는 onNavigate가 있으면 새 탭 대신 그 화면으로 간다. 값이 바뀌면(저장 뒤 다시 읽기) 새로 그린다.
 */
export function RichBody({ value, readPreview, onNavigate, label = "본문" }: {
  value: JSONContent; readPreview?: ReadLinkPreview; onNavigate?: (href: string) => void; label?: string
}) {
  // 같은 내용이면 다시 만들지 않는다(속성만 바뀐 상세를 다시 읽을 때 선택 영역과 그림을 지킨다).
  const versions = useRef<{ text: string; key: number }>({ text: "", key: 0 })
  const text = JSON.stringify(value)
  if (text !== versions.current.text) versions.current = { text, key: versions.current.key + 1 }
  return <RichEditor key={versions.current.key} value={value} isEditable={false} label={label} readPreview={readPreview} onNavigate={onNavigate} />
}

import type { JSONContent } from "@tiptap/react"
import { RichEditor } from "./RichEditor"
import type { LinkChoice, ReadLinkPreview, UploadFile } from "./types"

/**
 * 작성 양식 · 수정 화면의 본문 칸(Tiptap 3). 테두리와 고정 도구 막대 없이 종이 위에 쓰며, 서식은 글을 고르면 뜨는 도구 · `/`
 * 명령 · 블록 손잡이 메뉴 · 단축키 · 마크다운 입력 규칙으로 한다. 비어 있을 때 첫 줄에 안내를 둔다. 제목은 화면의 시스템 제목 하나라서
 * 본문의 제목은 2단계부터다. 올리기(upload)와 링크 미리보기(readPreview)는 호스트가 준다.
 */
export function RichDraft({ value, onChange, placeholder = "내용을 입력하세요", label = "본문", isPage = false, upload, readPreview, links }: {
  value?: JSONContent; onChange: (value: JSONContent) => void; placeholder?: string; label?: string; isPage?: boolean
  upload?: UploadFile; readPreview?: ReadLinkPreview; links?: LinkChoice[]
}) {
  return <RichEditor value={value} onChange={onChange} isEditable placeholder={placeholder} label={label} isPage={isPage} upload={upload} readPreview={readPreview} links={links} />
}

