  useEffect(() => { if (!isEditable) { setContext(null); setSlash(null); setSelected([]) } }, [isEditable])
  const hostValue = useMemo(() => ({ openZoom: setZoom, openHtml: setHtmlPage, readPreview }), [readPreview])

  // 읽는 화면에서 앱 안의 주소로 가는 링크(문서 언급, 블록 링크)는 새 탭을 열지 않고 그 화면으로 간다. 편집 중에는 누르기가 글 고르기라 두지 않는다.
  const followInside = (event: MouseEvent<HTMLDivElement>) => {
    if (isEditable || !onNavigate || event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return
    const href = (event.target as Element).closest("a")?.getAttribute("href")
    if (!href || !/^\/(?!\/)/.test(href)) return
    event.preventDefault()
    onNavigate(href)
  }

  if (!editor) return null
  let scrollParent = editor.isInitialized ? editor.view.dom.parentElement : null
  while (scrollParent && !/(auto|scroll)/.test(getComputedStyle(scrollParent).overflowY)) scrollParent = scrollParent.parentElement
  // 서식 도구는 본문 칸의 좌우 안에 머문다: 창 전체를 기준으로 두면 줄 첫머리를 골랐을 때 왼쪽 메뉴 밑으로 들어가 눌리지 않았다.
  const column = host.current?.getBoundingClientRect()
  const menuPadding = { top: 12, bottom: 84, left: Math.max(12, (column?.left ?? 12) - 8), right: Math.max(12, window.innerWidth - (column?.right ?? window.innerWidth) - 8) }
  const options = matching(slash?.query ?? "")
  const contextBlock = blocks.find(block => block.id === context)
  return (
    <EditorHostContext value={hostValue}>
      <div ref={host} data-editable={isEditable || undefined} data-dragging={isDragging || undefined} onClickCapture={followInside}
        className={cn("relative flex min-w-0 flex-col", EDITOR_COLOR_VARS)}
        onDragOver={event => { if (isEditable && Array.from(event.dataTransfer.types).includes("Files")) { event.preventDefault(); event.dataTransfer.dropEffect = "copy" } }}
        onDropCapture={event => {
          if (!isEditable || !event.dataTransfer.files.length) return
          event.preventDefault(); event.stopPropagation()
          const position = editor.view.posAtCoords({ left: event.clientX, top: event.clientY })?.pos
          editor.chain().focus().setTextSelection(position ?? editor.state.selection.from).run()
          pickFiles(Array.from(event.dataTransfer.files))
        }}
        onPointerDownCapture={event => { if ((event.target as Element).closest(".ProseMirror")) { setSelected([]); setContext(null) } }}
        onPointerMove={event => {
          // 손잡이가 있는 가장 가까운 블록을 찾는다: 목록 항목 안의 문단처럼 손잡이가 없는 블록 위에서는 그 목록의 손잡이를 보인다.
          let at = (event.target as Element).closest("[data-block-id]")
          while (at && !blocks.some(block => block.id === at!.getAttribute("data-block-id"))) at = at.parentElement?.closest("[data-block-id]") ?? null
          setHovered(at?.getAttribute("data-block-id") ?? null)
        }} onPointerLeave={() => setHovered(null)}>
        {isEditable ? <BubbleMenu editor={editor} updateDelay={0} className="z-40"
          shouldShow={({ editor: current, state, view, element, from, to }) => current.isEditable && state.selection instanceof TextSelection && !state.selection.empty
            && !!state.doc.textBetween(from, to).length && (view.hasFocus() || element.contains(element.ownerDocument.activeElement))}
          options={{ strategy: "fixed", placement: "top", offset: 10, scrollTarget: scrollParent ?? window, flip: { padding: menuPadding, fallbackPlacements: ["bottom"] },
            shift: { padding: menuPadding, crossAxis: true } }}>
          <SelectionMenu editor={editor} links={links} />
        </BubbleMenu> : null}
        {isEditable ? <TableControls editor={editor} host={host} atomic={atomic} /> : null}
        {error ? <p role="alert" className="mb-3 rounded-lg border border-destructive/40 bg-destructive/10 px-3 py-2 text-sm">{error}</p> : null}
        {uploads.panel}
        {frame ? frame(<EditorContent editor={editor} />) : <EditorContent editor={editor} />}
        {isEditable ? (
          // 손잡이는 글줄 왼쪽 바깥(1.625rem)에 둔다. 대화상자 · 페이지의 데스크톱 좌우 여백이 이 자리를 품는다.
          <div aria-label="본문 블록 조작" className="pointer-events-none absolute top-0 -left-6.5 w-6.5 print:hidden">
            {blocks.map((block, index) => (
              <div key={block.id} data-control-block={block.id} data-selected={selected.includes(block.id) || undefined} data-hovered={hovered === block.id || undefined}
                data-open={context === block.id || undefined} data-align-line={block.gripTop !== undefined || undefined}
                // 손잡이를 글줄 가운데에 맞춘다(높이의 절반만큼 올린다). transform으로 옮기면 그 안의 고정 위치 요소의 기준이 바뀌어 margin으로 옮긴다.
                className="pointer-events-auto absolute z-11 flex h-7.25 items-center opacity-0 transition-opacity hover:opacity-100 focus-within:opacity-100 data-hovered:opacity-100 data-open:z-30 data-open:opacity-100 data-selected:opacity-100 data-align-line:-mt-[0.90625rem] motion-reduce:transition-none"
                // check-ui: allow-style 손잡이 자리는 블록을 재서 정한다.
                style={{ top: block.gripTop ?? block.top, left: block.left }}>
                <EditorMenu label="블록 메뉴" side="left" open={context === block.id} onOpenChange={next => { if (!next) setContext(null) }}
                  entries={contextBlock && context === block.id ? blockMenuEntries({ editor, block: { id: block.id, pos: block.pos, size: block.size, type: block.type }, atomic, onStep: step }) : []}
                  trigger={<Tip label="끌어서 옮기기 · 눌러서 메뉴 · Shift/Ctrl 여러 개 고르기">
                    <Button variant="ghost" size="icon-sm" aria-label={`${index + 1}번 블록 선택`} data-grip="" aria-pressed={selected.includes(block.id)}
                      className="h-6.75 w-6 min-w-6 cursor-grab touch-none rounded-md p-0 text-icon-muted select-none hover:bg-accent hover:text-foreground aria-pressed:text-foreground"
                      onContextMenu={event => { event.preventDefault(); setSelected([block.id]); setContext(block.id) }}
                      onPointerDown={event => {
                        if (event.button !== 0) return
                        event.preventDefault(); event.currentTarget.focus({ preventScroll: true })
                        dragging.current = { ids: selected.includes(block.id) ? selected : [block.id], x: event.clientX, y: event.clientY, active: false }
                      }}
                      onClick={event => {
                        if (skipClick.current) return
                        if (event.shiftKey && selected.length) {
                          const from = blocks.findIndex(each => each.id === selected[0])
                          setSelected(blocks.slice(Math.min(from, index), Math.max(from, index) + 1).map(each => each.id))
                        } else if (event.ctrlKey || event.metaKey) setSelected(previous => previous.includes(block.id) ? previous.filter(id => id !== block.id) : [...previous, block.id])
                        else setSelected([block.id])
                        setContext(event.shiftKey || event.ctrlKey || event.metaKey ? null : context === block.id ? null : block.id)
                      }}>
                      <GripIcon />
                    </Button>
                  </Tip>} />
              </div>
            ))}
          </div>
        ) : null}
        {drop ? (
          // check-ui: allow-style 놓을 자리는 블록을 재서 정한다.
          <div data-invalid={drop.error ? "" : undefined} className="pointer-events-none absolute z-17 h-[3px] bg-ring data-invalid:bg-destructive" style={{ top: drop.top, left: drop.left, width: drop.width }}>
            <span className="absolute top-1 left-1 rounded-sm bg-foreground px-1.75 py-0.75 text-[0.625rem] whitespace-nowrap text-background">{drop.error ?? drop.label}</span>
          </div>
        ) : null}
        {isEditable && isDragging ? <div data-editor-end="" aria-hidden className="min-h-6 cursor-grabbing" /> : null}
        {/* 파일 고르기는 브라우저의 파일 입력이 맡는다(보이지 않는 입력). */}
        <input hidden ref={fileInput} type="file" multiple aria-label="파일 첨부" onChange={event => { pickFiles(Array.from(event.target.files ?? [])); event.target.value = "" }} />
        {slash && isEditable ? (
          <div ref={palette} role="dialog" aria-label="블록 추가 메뉴"
            className="fixed z-55 box-border flex w-80 max-w-[calc(100vw-1.5rem)] flex-col overflow-hidden rounded-lg border border-input bg-popover py-1.25 text-popover-foreground shadow-md"
            // check-ui: allow-style `/` 목록은 커서 자리를 재서 놓는다.
            style={paletteBox}>
            <div className="min-h-0 flex-1 overflow-y-auto overscroll-contain px-1.25">
              {options.map((command, index) => {
                const Icon = COMMAND_ICONS[command.id]
                return (
                  <div key={command.id} className="contents">
                    {index === 0 || options[index - 1].group !== command.group
                      ? <div className="px-2.25 pt-2.5 pb-1.5 text-[0.625rem] font-medium tracking-[0.02em] text-muted-foreground">{command.group}</div> : null}
                    <button type="button" data-active={index === active || undefined} onMouseDown={keepSelection} onMouseEnter={() => setActive(index)} onClick={() => run(command.id)}
                      className="flex min-h-11.25 w-full items-center gap-2.5 rounded-md px-1.75 py-1.25 text-left outline-none data-active:bg-accent max-md:min-h-12">
                      <span className="grid size-7.5 flex-none place-items-center rounded-md border text-icon-muted [&_svg]:size-4.5"><Icon /></span>
                      <span className="flex min-w-0 flex-col leading-[1.35]">
                        <span className="text-sm font-medium">{command.label}</span><span className="text-xs text-muted-foreground">{command.hint}</span>
                      </span>
                    </button>
                  </div>
                )
              })}
              {!options.length ? <p className="p-3 text-xs text-muted-foreground">일치하는 블록이 없습니다.</p> : null}
            </div>
            <div className="mt-1.25 flex flex-none items-center justify-between border-t px-2.5 pt-1 text-xs text-muted-foreground">
              <span className="flex items-center gap-1 [&_svg]:size-3"><ArrowUpDownIcon />이동<CornerDownLeftIcon />추가</span>
              <Button variant="ghost" size="xs" onClick={() => { setSlash(null); editor.commands.focus() }}>
                닫기<kbd className="rounded border px-1 font-mono text-[0.625rem]">esc</kbd>
              </Button>
            </div>
          </div>
        ) : null}
      </div>
      <ZoomHost slide={zoom} page={htmlPage} onClose={() => { setZoom(null); setHtmlPage(null) }} />
    </EditorHostContext>
  )
}

import type { Editor } from "@tiptap/react"
import { useEffect, useState } from "react"
import { BoldIcon, ChevronDownIcon, CodeIcon, EraserIcon, ItalicIcon, Link2Icon, MoreHorizontalIcon, StrikethroughIcon, UnderlineIcon } from "@/shared/ui/icon"
import { ALIGN_LABELS, AlignGlyph, IndentGlyph, Script, Swatch, TEXT_BLOCKS, colorEntries, textBlockOf, turnInto, turnIntoEntries, type Align } from "./format"
import { LinkPanel } from "./LinkPanel"
import { EditorMenu, EditorPopover, keepSelection, MOD, type MenuEntry } from "./menu"
import { ToolButton, ToolDivider } from "./tool"
import type { LinkChoice } from "./types"

type Panel = "type" | "color" | "more" | "link"

/** 색을 입히거나 지운다. 빈 값은 기본(색 없음)이다. */
export const setInk = (editor: Editor, color: string) => color ? editor.chain().focus().setColor(color).run() : editor.chain().focus().unsetColor().run()
export const setFill = (editor: Editor, color: string) => color ? editor.chain().focus().setHighlight({ color }).run() : editor.chain().focus().unsetHighlight().run()

/**
 * 글을 고르면 그 위에 뜨는 서식 도구. 왼쪽부터 블록 종류, 굵게 · 기울임 · 밑줄 · 취소선 · 코드, 링크, 색, 더 보기다. 종류 · 색 ·
 * 더 보기(위 · 아래 첨자, 줄 정렬, 내어쓰기 · 들여쓰기, 서식 지우기)는 메뉴, 링크는 입력 판으로 펼친다(휴대폰은 바텀시트).
 * 좁은 화면에서 도구가 넘치면 띠 안에서 가로로 민다.
 */
export function SelectionMenu({ editor, links }: { editor: Editor; links?: LinkChoice[] }) {
  const [open, setOpen] = useState<Panel | null>(null)
  const isEmpty = editor.state.selection.empty
  // 선택이 풀려 도구가 사라지면 펼친 것도 접는다.
  useEffect(() => { if (isEmpty) setOpen(null) }, [isEmpty])
  const chain = () => editor.chain().focus()
  const toggle = (panel: Panel) => (next: boolean) => setOpen(next ? panel : null)
  const type = textBlockOf(editor), ink = String(editor.getAttributes("textStyle").color ?? ""), fill = String(editor.getAttributes("highlight").color ?? "")
  const align = (editor.getAttributes("paragraph").textAlign ?? editor.getAttributes("heading").textAlign ?? "left") as Align
  const listItem = editor.isActive("taskItem") ? "taskItem" : "listItem"
  const mark = (label: string, name: string, run: () => unknown, Icon: typeof BoldIcon, shortcut?: string) =>
    <ToolButton label={label} tip={shortcut ? `${label} (${shortcut})` : label} aria-pressed={editor.isActive(name)} onMouseDown={keepSelection} onClick={() => run()}><Icon /></ToolButton>
  const more: MenuEntry[] = [
    { kind: "item", label: "위 첨자", icon: <Script isUp />, isChecked: editor.isActive("superscript"), onSelect: () => chain().toggleSuperscript().run() },
    { kind: "item", label: "아래 첨자", icon: <Script isUp={false} />, isChecked: editor.isActive("subscript"), onSelect: () => chain().toggleSubscript().run() },
    { kind: "separator" },
    ...(["left", "center", "right", "justify"] as const).map(kind => ({ kind: "item" as const, label: ALIGN_LABELS[kind], icon: <AlignGlyph kind={kind} />, isChecked: align === kind,
      onSelect: () => chain().setTextAlign(kind).run() })),
    { kind: "separator" },
    { kind: "item", label: "내어쓰기", icon: <IndentGlyph isOut />, hint: "Shift+Tab", isDisabled: !editor.can().liftListItem(listItem), onSelect: () => chain().liftListItem(listItem).run() },
    { kind: "item", label: "들여쓰기", icon: <IndentGlyph />, hint: "Tab", isDisabled: !editor.can().sinkListItem(listItem), onSelect: () => chain().sinkListItem(listItem).run() },
    { kind: "separator" },
    { kind: "item", label: "서식 지우기", icon: <EraserIcon />, onSelect: () => chain().unsetAllMarks().run() },
  ]
  return (
    <div role="toolbar" aria-label="선택 텍스트 서식"
      className="flex items-center gap-0.5 rounded-xl border border-input bg-popover p-1 text-popover-foreground shadow-md max-md:max-w-[calc(100vw-1.25rem)] max-md:overflow-x-auto">
      <EditorMenu label="블록 종류" open={open === "type"} onOpenChange={toggle("type")}
        entries={turnIntoEntries(type, id => turnInto(editor, id))}
        trigger={<ToolButton label="블록 종류" tip="블록 종류" isWide onMouseDown={keepSelection}>
          {TEXT_BLOCKS.find(block => block.id === type)?.label ?? "텍스트"}<ChevronDownIcon />
        </ToolButton>} />
      <ToolDivider />
      {mark("굵게", "bold", () => chain().toggleBold().run(), BoldIcon, `${MOD}+B`)}
      {mark("기울임", "italic", () => chain().toggleItalic().run(), ItalicIcon, `${MOD}+I`)}
      {mark("밑줄", "underline", () => chain().toggleUnderline().run(), UnderlineIcon, `${MOD}+U`)}
      {mark("취소선", "strike", () => chain().toggleStrike().run(), StrikethroughIcon)}
      {mark("인라인 코드", "code", () => chain().toggleCode().run(), CodeIcon)}
      <ToolDivider />
      <EditorPopover label="링크" open={open === "link"} onOpenChange={toggle("link")}
        trigger={<ToolButton label="링크" aria-pressed={editor.isActive("link")} onMouseDown={keepSelection}><Link2Icon /></ToolButton>}>
        <LinkPanel editor={editor} links={links} onDone={() => setOpen(null)} />
      </EditorPopover>
      <EditorMenu label="색" open={open === "color"} onOpenChange={toggle("color")} align="end"
        entries={colorEntries(ink, fill, color => setInk(editor, color), color => setFill(editor, color))}
        trigger={<ToolButton label="색" isWide onMouseDown={keepSelection}><Swatch ink={ink || undefined} fill={fill || undefined} isFramed /><ChevronDownIcon /></ToolButton>} />
      <ToolDivider />
      <EditorMenu label="더 많은 서식" open={open === "more"} onOpenChange={toggle("more")} align="end" entries={more}
        trigger={<ToolButton label="더 보기" onMouseDown={keepSelection}><MoreHorizontalIcon className="rotate-90" /></ToolButton>} />
    </div>
  )
}

import { closeHistory } from "@tiptap/pm/history"
import { NodeViewWrapper, ReactNodeViewRenderer, type NodeViewProps } from "@tiptap/react"
import { useEffect, useLayoutEffect, useMemo, useRef, useState, type KeyboardEvent } from "react"
import { cn } from "@/shared/lib/utils"
import { Button } from "@/shared/ui/button"
import { GlobeIcon, PencilIcon, ZoomInIcon } from "@/shared/ui/icon"
import { Input } from "@/shared/ui/input"
import { Textarea } from "@/shared/ui/textarea"
import { diagramColors, embedURL, useDiagram } from "./diagram"
import { LinkCard } from "./LinkCard"
import { BlockTool, BlockTools, CopyButton, useEditable } from "./MediaView"
import { SOURCE_EXAMPLES, sourceNode, type SourceKind } from "./schema"
import { ZONE, ZONE_ART } from "./upload-zone"
import { diagramSlide, useEditorHost } from "./zoom"

const LABELS: Record<SourceKind, string> = { mermaidBlock: "Mermaid", webEmbed: "링크 카드" }
const ERROR = "rounded-lg border border-destructive/30 bg-destructive/8 px-3 py-2 text-xs text-destructive"

/** 그린 SVG는 Mermaid가 만든 글이라(securityLevel strict) 그대로 넣는다. 높이는 36rem까지다. */
function MermaidSvg({ html }: { html: string }) {
  const box = useRef<HTMLDivElement>(null)
  useLayoutEffect(() => { if (box.current) box.current.innerHTML = html }, [html])
  return <div ref={box} className="block w-full text-center [&_svg]:mx-auto [&_svg]:block [&_svg]:max-h-[36rem]" />
}

/**
 * 원문 하나로 그리는 블록의 노드 뷰: Mermaid 도표와 링크 카드. 도표는 틀 없이 칸 폭을 채우고(원래 크기의 3배까지, 높이 36rem 안),
 * 도구(크게 보기 · 원문 복사 · 편집)는 포인터를 올리거나 초점이 들어오면 오른쪽 위에 뜬다. 원문 편집 칸은 테마 색을 따른다.
 * 링크 카드는 주소를 넣는 점선 칸(올리는 칸과 같은 모양)과 카드로 보인다.
 */
function SourceView({ node, editor, updateAttributes, getPos, selected }: NodeViewProps) {
  const kind = node.type.name as SourceKind, source = String(node.attrs.source ?? ""), label = LABELS[kind]
  const isEditable = useEditable(editor)
  const [isEditing, setEditing] = useState(false), [draft, setDraft] = useState(source)
  const textarea = useRef<HTMLTextAreaElement>(null), address = useRef<HTMLInputElement>(null), previewBox = useRef<HTMLDivElement>(null)
  const { openZoom } = useEditorHost()
  const diagram = useDiagram(isEditing ? draft : source, kind === "mermaidBlock")
  const embed = useMemo(() => {
    if (kind !== "webEmbed") return { error: "" }
    const value = isEditing ? draft : source
    if (!value.trim()) return { error: "웹 주소를 입력하세요." }
    try { return { ...embedURL(value), error: "" } } catch (error) { return { error: (error as Error).message } }
  }, [kind, isEditing, draft, source])
  const preview = kind === "mermaidBlock" ? diagram : { pending: false, error: embed.error, html: "" }
  useEffect(() => { setEditing(editor.isEditable && !source.trim()); setDraft(source) }, [source])
  useEffect(() => { if (!isEditable) setEditing(false) }, [isEditable])
  useEffect(() => { if (isEditing) (textarea.current ?? address.current)?.focus() }, [isEditing])
  const start = () => { if (!isEditable) return; setDraft(source); setEditing(true) }
  // 도표를 크게 보기 창으로 연다(지금 화면 색표의 바탕을 깐 채로).
  const zoom = () => {
    const slide = diagramSlide(previewBox.current?.querySelector("svg"), diagramColors[diagram.scheme].background, `${label} 크게 보기`)
    if (slide) openZoom(slide)
  }
  // 취소: 아직 주소가 없는 새 링크 카드는 빈 블록을 남기지 않고 지운다.
  const cancel = () => {
    const pos = getPos()
    if (kind === "webEmbed" && !source.trim() && typeof pos === "number") { editor.chain().focus().deleteRange({ from: pos, to: pos + node.nodeSize }).run(); return }
    setDraft(source); setEditing(false); editor.commands.focus()
  }
  const apply = () => {
    if (!isEditable || preview.pending || preview.error) return
    editor.view.dispatch(closeHistory(editor.state.tr))
    updateAttributes({ source: draft.trim() })
    editor.view.dispatch(closeHistory(editor.state.tr))
    setEditing(false)
    const pos = getPos()
    if (typeof pos === "number") editor.chain().focus().setNodeSelection(pos).run()
  }
  const keys = (isMultiline: boolean) => (event: KeyboardEvent) => {
    if (event.nativeEvent.isComposing) return
    if (event.key === "Escape") { event.preventDefault(); event.stopPropagation(); cancel() }
    if (event.key === "Enter" && (!isMultiline || event.ctrlKey || event.metaKey)) { event.preventDefault(); event.stopPropagation(); apply() }
  }
  const render = () => preview.pending ? <p role="status" className="text-xs text-muted-foreground">미리보기 만드는 중…</p>
    : preview.error ? <p role="alert" className={ERROR}>{label}를 표시할 수 없습니다. {preview.error}</p>
      : kind === "webEmbed" && "host" in embed && embed.host ? <LinkCard url={embed.original} host={embed.host} isEditable={isEditable} onEdit={start} />
        : <MermaidSvg html={diagram.html} />
  return (
    <NodeViewWrapper as="div" data-selected={selected && isEditable ? "" : undefined} data-rich-type={kind} data-block-id={node.attrs.blockId ?? undefined} contentEditable={false}
      className={cn("group/block relative", kind === "webEmbed" ? "my-3.5" : "my-(--block-gap)")}>
      {kind === "mermaidBlock" ? (
        <BlockTools>
          {!isEditing && !preview.pending && !preview.error ? <BlockTool label="다이어그램 크게 보기" tip="크게 보기" onClick={zoom}><ZoomInIcon /></BlockTool> : null}
          <CopyButton text={source} label="Mermaid 원문 복사" />
          {isEditable && !isEditing ? <BlockTool label={`${label} 편집`} tip="편집" onClick={start}><PencilIcon /></BlockTool> : null}
        </BlockTools>
      ) : null}
      {kind === "webEmbed" && isEditing ? null : (
        <div ref={previewBox} onDoubleClick={kind === "mermaidBlock" ? (isEditable ? start : zoom) : undefined}
          className={cn(kind === "mermaidBlock" && "flex justify-center rounded-[0.625rem] py-2 group-data-selected/block:outline-2 group-data-selected/block:outline-offset-4 group-data-selected/block:outline-ring",
            kind === "mermaidBlock" && !isEditable && "cursor-zoom-in")}>
          {render()}
        </div>
      )}
      {isEditable && isEditing && kind === "webEmbed" ? (
        <div role="group" aria-label="링크 카드 주소 넣기" className={cn(ZONE, "my-0 flex flex-col items-center gap-2 px-4 py-7 text-center text-sm text-foreground hover:border-input hover:bg-accent")}>
          <span className={ZONE_ART}><GlobeIcon /></span>
          <span>카드로 보여 줄 웹 페이지 주소를 붙여 넣으세요</span>
          <Input ref={address} aria-label="웹 주소" value={draft} placeholder="https://" className="w-[min(30rem,100%)] bg-card text-center"
            onChange={event => setDraft(event.target.value)} onKeyDown={keys(false)} />
          <span role={draft.trim() && preview.error ? "alert" : undefined} className={cn("text-xs text-muted-foreground", draft.trim() && preview.error && "text-destructive")}>
            {draft.trim() && preview.error ? preview.error : "그 페이지의 제목 · 설명 · 대표 사진을 카드로 보여 줍니다 · HTTPS 주소만 · Enter 넣기 · Esc 취소"}
          </span>
          <div className="flex gap-1.5">
            <Button variant="ghost" size="sm" className="max-md:h-11" onClick={cancel}>취소</Button>
            <Button size="sm" className="max-md:h-11" disabled={!draft.trim() || !!preview.error} onClick={apply}>넣기</Button>
          </div>
        </div>
      ) : null}
      {isEditable && isEditing && kind === "mermaidBlock" ? (
        <div role="group" aria-label={`${label} 원문 편집`} className="mt-2 flex flex-col gap-2 rounded-xl border bg-muted px-3.5 py-3 text-foreground">
          <span className="text-xs text-muted-foreground">Mermaid 원문</span>
          <Textarea ref={textarea} aria-label={`${label} 원문`} value={draft} rows={6} placeholder={SOURCE_EXAMPLES.mermaidBlock}
            className="bg-card font-mono text-[0.8125rem] leading-relaxed" onChange={event => setDraft(event.target.value)} onKeyDown={keys(true)} />
          <div className="flex flex-wrap items-center justify-end gap-2">
            <span className="text-xs text-muted-foreground max-md:hidden">Ctrl+Enter 적용 · Esc 취소</span>
            <Button variant="ghost" size="sm" className="max-md:h-11" onClick={cancel}>취소</Button>
            <Button size="sm" className="max-md:h-11" disabled={preview.pending || !!preview.error} onClick={apply}>적용</Button>
          </div>
        </div>
      ) : null}
      {!isEditing && preview.error && kind === "mermaidBlock" ? <p className="mt-2 text-xs whitespace-pre-wrap text-muted-foreground">{source || `${label}를 편집해 주세요.`}</p> : null}
    </NodeViewWrapper>
  )
}

export const sourceNodeViews = (["mermaidBlock", "webEmbed"] as SourceKind[]).map(kind => sourceNode(kind).extend({ addNodeView() { return ReactNodeViewRenderer(SourceView) } }))

import { TextSelection } from "@tiptap/pm/state"
import { moveTableColumn, moveTableRow, selectedRect } from "@tiptap/pm/tables"
import type { Editor } from "@tiptap/react"
import { useCallback, useEffect, useLayoutEffect, useRef, useState, type CSSProperties, type ReactNode, type RefObject } from "react"
import { cn } from "@/shared/lib/utils"
import { ArrowDownIcon, ArrowLeftIcon, ArrowRightIcon, ArrowUpIcon, GripIcon, MoreHorizontalIcon, PlusIcon, TableIcon, Trash2Icon } from "@/shared/ui/icon"
import { EditorMenu, keepSelection, type MenuEntry } from "./menu"
import { Tip } from "./tool"

/** 손잡이 · 단추가 놓일 자리(에디터 틀 기준 px). 표가 가로로 넘치면 보이는 부분에 맞춘다. */
type Box = { left: number; top: number; width: number; height: number; row?: { top: number; height: number }; col?: { left: number; width: number } }
type Kind = "row" | "col" | "table"
const LABEL = { row: "행 메뉴", col: "열 메뉴", table: "표 메뉴" } as const

const cellOf = (node: EventTarget | Node | null) => (node instanceof Element ? node : node instanceof Node ? node.parentElement : null)?.closest<HTMLTableCellElement>("td,th") ?? null

/** 표 손잡이: 테두리 있는 작은 단추. 가리키거나 메뉴가 열리면 글자색으로 칠한다. 손가락으로 누를 자리는 보이는 것보다 넓다. */
const HANDLE = "absolute grid place-items-center rounded-[0.3125rem] border border-input bg-card text-icon-muted shadow-xs outline-none [&_svg]:size-3 "
  + "hover:border-transparent hover:bg-foreground hover:text-background aria-expanded:border-transparent aria-expanded:bg-foreground aria-expanded:text-background "
  + "focus-visible:ring-3 focus-visible:ring-ring/50 after:absolute after:-inset-2 after:content-['']"
const ADD = "absolute grid place-items-center rounded-sm bg-accent text-icon-muted outline-none [&_svg]:size-3 hover:bg-pressed hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/50"

/**
 * 표 둘레의 편집 도구. 표 바로 옆에서 고친다: 포인터가 있는 칸(없으면 커서가 있는 칸)의 행 왼쪽 · 열 위쪽에 손잡이가 뜨고,
 * 누르면 그 행 · 열의 메뉴(추가 · 이동 · 머리글 · 삭제)가 열린다. 표 오른쪽 · 아래 가장자리의 + 막대는 끝에 열 · 행을 더하고, 왼쪽 위
 * 모서리 단추는 표 전체의 메뉴(셀 병합 · 나누기 · 머리글 · 표 삭제)다. 열 너비는 열 경계를 끌어 바꾼다(ResizableTable).
 * 병합된 칸이 섞인 표에서는 손잡이가 그 칸의 첫 행 · 열을 가리키며, 터치 화면에서는 커서가 있는 칸 기준으로만 뜬다.
 * 메뉴는 데스크톱 드롭다운, 휴대폰 바텀시트다. 손잡이 자리는 표를 재서 정하므로 인라인 위치를 쓴다.
 */
export function TableControls({ editor, host, atomic }: { editor: Editor; host: RefObject<HTMLElement | null>; atomic: (fn: () => unknown) => void }) {
  const [hover, setHover] = useState<HTMLTableCellElement | null>(null), [box, setBox] = useState<Box | null>(null), [menu, setMenu] = useState<Kind | null>(null), [tick, setTick] = useState(0)
  const leave = useRef<number | undefined>(undefined), frozen = useRef<HTMLTableCellElement | null>(null)
  // 지금 가리키는 칸: 메뉴가 열려 있으면 그 칸을 붙잡고, 아니면 포인터가 있는 칸, 그것도 없으면 커서가 있는 칸.
  const caretCell = useCallback(() => { try { return cellOf(editor.view.domAtPos(editor.state.selection.from).node) } catch { return null } }, [editor])
  const current = useCallback(() => { const cell = frozen.current ?? hover; return cell?.isConnected && editor.view.dom.contains(cell) ? cell : caretCell() }, [editor, hover, caretCell])

  const measure = useCallback(() => {
    const frame = host.current, cell = current(), table = cell?.closest("table"), wrapper = table?.closest<HTMLElement>(".tableWrapper") ?? table
    if (!frame || !cell || !table || !wrapper) { setBox(null); return }
    const origin = frame.getBoundingClientRect(), outer = wrapper.getBoundingClientRect(), inner = table.getBoundingClientRect()
    const row = cell.parentElement!.getBoundingClientRect(), own = cell.getBoundingClientRect()
    const left = Math.max(outer.left, inner.left), right = Math.min(outer.right, inner.right), center = own.left + own.width / 2
    setBox({ left: left - origin.left, top: inner.top - origin.top, width: right - left, height: inner.height, row: { top: row.top - origin.top, height: row.height },
      col: center >= left && center <= right ? { left: own.left - origin.left, width: own.width } : undefined })
  }, [host, current])
  useLayoutEffect(measure, [measure, tick])
  // 본문이 바뀌거나 커서가 옮겨 가면, 창 크기가 바뀌면, 넘치는 표를 가로로 굴리면 다시 잰다.
  useEffect(() => {
    const again = () => setTick(value => value + 1)
    editor.on("transaction", again); window.addEventListener("resize", again)
    const frame = host.current, scrolled = (event: Event) => { if ((event.target as Element | null)?.classList?.contains("tableWrapper")) again() }
    frame?.addEventListener("scroll", scrolled, true)
    return () => { editor.off("transaction", again); window.removeEventListener("resize", again); frame?.removeEventListener("scroll", scrolled, true) }
  }, [editor, host])
  // 포인터가 표의 칸 위에 있으면 그 칸을, 도구 위에 있으면 그대로 두고, 벗어나면 잠시 뒤 놓는다(칸에서 손잡이로 건너갈 틈).
  useEffect(() => {
    const frame = host.current
    if (!frame) return
    const later = () => { window.clearTimeout(leave.current); leave.current = window.setTimeout(() => setHover(null), 220) }
    const moved = (event: MouseEvent) => {
      const target = event.target as Element | null
      if (target?.closest("[data-table-controls]")) { window.clearTimeout(leave.current); return }
      const cell = cellOf(target)
      if (cell && editor.view.dom.contains(cell)) { window.clearTimeout(leave.current); setHover(cell) } else later()
    }
    frame.addEventListener("mousemove", moved); frame.addEventListener("mouseleave", later)
    return () => { window.clearTimeout(leave.current); frame.removeEventListener("mousemove", moved); frame.removeEventListener("mouseleave", later) }
  }, [editor, host])
  const close = useCallback(() => { frozen.current = null; setMenu(null) }, [])

  if (!box) return null
  /** 커서를 그 칸 안에 둔다(표 명령은 커서가 있는 칸을 기준으로 움직인다). */
  const into = (cell: HTMLTableCellElement | null) => {
    if (!cell?.isConnected) return false
    const pos = editor.view.posAtDOM(cell, 0), { doc, tr } = editor.state
    editor.view.dispatch(tr.setSelection(TextSelection.near(doc.resolve(Math.min(pos + 1, doc.content.size)))))
    return true
  }
  /** 손잡이가 가리키는 칸에 커서를 두고 명령을 한 번의 실행 취소 단위로 돌린다. 표 메뉴는 고른 칸(셀 병합)을 지킨다. */
  const act = (fn: () => unknown, keepsSelection: boolean) => () => {
    const cell = frozen.current ?? current()
    close(); setHover(null)
    atomic(() => { if (!keepsSelection || caretCell()?.closest("table") !== cell?.closest("table")) into(cell); fn() })
    editor.commands.focus()
  }
  const chain = () => editor.chain().focus()
  const shift = (axis: "row" | "col", by: number) => () => {
    const rect = selectedRect(editor.state), from = axis === "row" ? rect.top : rect.left, size = axis === "row" ? rect.map.height : rect.map.width, to = from + by
    if (to < 0 || to >= size) return
    ;(axis === "row" ? moveTableRow : moveTableColumn)({ from, to })(editor.state, editor.view.dispatch)
  }
  /** 끝에 행 · 열을 더한다: 마지막 칸에 커서를 두고 그 뒤에 더한다. */
  const extend = (axis: "row" | "col") => () => {
    const cells = current()?.closest("table")?.querySelectorAll<HTMLTableCellElement>("td,th"), last = cells?.[cells.length - 1] ?? null
    setHover(null)
    atomic(() => { if (into(last)) (axis === "row" ? chain().addRowAfter() : chain().addColumnAfter()).run() })
  }
  const item = (label: string, icon: ReactNode, run: () => unknown, kind: Kind, options: { isEnabled?: boolean; isDanger?: boolean } = {}): MenuEntry =>
    ({ kind: "item", label, icon, isDisabled: options.isEnabled === false, isDanger: options.isDanger, onSelect: act(run, kind === "table") })
  const entries: Record<Kind, () => MenuEntry[]> = {
    row: () => [item("위에 행 추가", <ArrowUpIcon />, () => chain().addRowBefore().run(), "row"), item("아래에 행 추가", <ArrowDownIcon />, () => chain().addRowAfter().run(), "row"),
      item("위로 옮기기", <ArrowUpIcon />, shift("row", -1), "row"), item("아래로 옮기기", <ArrowDownIcon />, shift("row", 1), "row"),
      item("머리글 행 켜기 · 끄기", <TableIcon />, () => chain().toggleHeaderRow().run(), "row"), { kind: "separator" },
      item("행 삭제", <Trash2Icon />, () => chain().deleteRow().run(), "row", { isDanger: true })],
    col: () => [item("왼쪽에 열 추가", <ArrowLeftIcon />, () => chain().addColumnBefore().run(), "col"), item("오른쪽에 열 추가", <ArrowRightIcon />, () => chain().addColumnAfter().run(), "col"),
      item("왼쪽으로 옮기기", <ArrowLeftIcon />, shift("col", -1), "col"), item("오른쪽으로 옮기기", <ArrowRightIcon />, shift("col", 1), "col"),
      item("머리글 열 켜기 · 끄기", <TableIcon />, () => chain().toggleHeaderColumn().run(), "col"), { kind: "separator" },
      item("열 삭제", <Trash2Icon />, () => chain().deleteColumn().run(), "col", { isDanger: true })],
    table: () => [item("셀 병합", <PlusIcon />, () => chain().mergeCells().run(), "table", { isEnabled: editor.can().mergeCells() }),
      item("셀 나누기", <TableIcon />, () => chain().splitCell().run(), "table", { isEnabled: editor.can().splitCell() }),
      item("머리글 행 켜기 · 끄기", <TableIcon />, () => chain().toggleHeaderRow().run(), "table"), item("머리글 열 켜기 · 끄기", <TableIcon />, () => chain().toggleHeaderColumn().run(), "table"),
      { kind: "separator" }, item("표 삭제", <Trash2Icon />, () => chain().deleteTable().run(), "table", { isDanger: true })],
  }
  const handle = (kind: Kind, place: CSSProperties, drawing: ReactNode, size: string) => (
    <EditorMenu key={kind} label={LABEL[kind]} open={menu === kind} side={kind === "col" ? "bottom" : "right"} className="w-52"
      onOpenChange={next => { if (next) { frozen.current = current(); setMenu(kind) } else close() }} entries={menu === kind ? entries[kind]() : []}
      trigger={<Tip label={LABEL[kind]}>
        {/* check-ui: allow-style 손잡이 자리는 표를 재서 정한다. */}
        <button type="button" aria-label={LABEL[kind]} className={cn(HANDLE, size)} style={place} onMouseDown={keepSelection}>{drawing}</button>
      </Tip>} />
  )
  return (
    <div data-table-controls="" aria-label="표 편집" className="pointer-events-none absolute inset-0 z-12 *:pointer-events-auto">
      {handle("table", { left: box.left - 9, top: box.top - 9 }, <MoreHorizontalIcon />, "size-4.5 rounded-full")}
      {box.row ? handle("row", { left: box.left - 8, top: box.row.top + box.row.height / 2 - 11 }, <GripIcon />, "h-5.5 w-4") : null}
      {box.col ? handle("col", { left: box.col.left + box.col.width / 2 - 11, top: box.top - 8 }, <MoreHorizontalIcon />, "h-4 w-5.5") : null}
      <Tip label="끝에 열 추가">
        {/* check-ui: allow-style 막대 자리와 길이는 표를 재서 정한다. */}
        <button type="button" aria-label="끝에 열 추가" className={cn(ADD, "w-3.5")} style={{ left: box.left + box.width + 4, top: box.top, height: box.height }}
          onMouseDown={keepSelection} onClick={extend("col")}><PlusIcon /></button>
      </Tip>
      <Tip label="끝에 행 추가">
        {/* check-ui: allow-style 막대 자리와 길이는 표를 재서 정한다. */}
        <button type="button" aria-label="끝에 행 추가" className={cn(ADD, "h-3.5")} style={{ left: box.left, top: box.top + box.height + 4, width: box.width }}
          onMouseDown={keepSelection} onClick={extend("row")}><PlusIcon /></button>
      </Tip>
    </div>
  )
}

import { useLayoutEffect, useRef } from "react"
import Lightbox from "yet-another-react-lightbox"
import Zoom from "yet-another-react-lightbox/plugins/zoom"
import "yet-another-react-lightbox/styles.css"
import type { DiagramSlide, ZoomSlide } from "./zoom"

/** 카드 안쪽 여백(양쪽)을 뺀 창 안에 도표를 맞춘다. */
const PADDING = 48

/** 도표를 그린 SVG 그대로 넣는다. 확대 · 이동은 Zoom 플러그인이 이 상자 전체에 건다. */
function DiagramView({ slide, rect }: { slide: DiagramSlide; rect: { width: number; height: number } }) {
  const box = useRef<HTMLDivElement>(null)
  useLayoutEffect(() => { if (box.current) box.current.innerHTML = slide.svg }, [slide.svg])
  const scale = Math.min((rect.width - PADDING) / slide.width, (rect.height - PADDING) / slide.height)
  return (
    <div ref={box} role="img" aria-label={slide.label} className="box-content block rounded-xl p-6 [&_svg]:block [&_svg]:size-full [&_svg]:max-w-none"
      // check-ui: allow-style 크기와 바탕색은 도표마다 다르다(도표 원래 크기와 그 색표의 바탕).
      style={{ inlineSize: slide.width * scale, blockSize: slide.height * scale, backgroundColor: slide.background }} />
  )
}

/**
 * 사진과 도표를 크게 보는 창(yet-another-react-lightbox + Zoom). 휠 · 두 손가락 · 두 번 눌러 확대, 끌어서 이동, Esc와 바깥 누르기로
 * 닫기, 초점 가두기를 라이브러리가 맡는다. 한 장만 보이므로 이전 · 다음 단추는 없앤다. 어두운 막 위에 한 장을 둔다.
 */
export default function ZoomViewer({ slide, onClose }: { slide: ZoomSlide; onClose: () => void }) {
  return (
    <Lightbox open close={onClose} slides={[slide]} plugins={[Zoom]} carousel={{ finite: true }} controller={{ closeOnBackdropClick: true }}
      zoom={{ supports: ["diagram"], maxZoomPixelRatio: 4, maxZoom: 6, scrollToZoom: true }}
      labels={{ Close: "닫기", "Zoom in": "확대", "Zoom out": "축소", Lightbox: "크게 보기", Carousel: "크게 보기", Slide: "보기", "Photo gallery": "크게 보기", "{index} of {total}": "{index} / {total}" }}
      render={{ buttonPrev: () => null, buttonNext: () => null,
        slide: ({ slide: shown, rect }) => shown.type === "diagram" ? <DiagramView slide={shown as DiagramSlide} rect={rect} /> : undefined }}
      // 막 색은 라이브러리의 변수로만 바꿀 수 있다(밑줄이 든 이름이라 클래스로 쓰기 어렵다).
      styles={{ root: { "--yarl__color_backdrop": "color-mix(in srgb, black 88%, transparent)" } as Record<string, string> }} />
  )
}

import { closeHistory } from '@tiptap/pm/history';
import { Fragment, type Node as ProseNode } from '@tiptap/pm/model';
import { TextSelection, type EditorState, type Transaction } from '@tiptap/pm/state';

export type TreeBlock = { id: string; pos: number; node: ProseNode; index: number };
export type Destination = { anchorId?: string; side?: 'before' | 'after' };

/**
 * 옮길 수 있는 블록: 문서 바로 아래의 블록. 표 칸·목록 항목은 그 안의 편집 규칙을 따르므로 손잡이를 두지 않는다.
 * (토글·열·콜아웃처럼 블록을 담는 블록은 이 키트에 없다.)
 */
export function blockTree(doc: ProseNode): TreeBlock[] {
  const blocks: TreeBlock[] = [];
  doc.forEach((node, offset, index) => { const id = node.attrs.blockId as string | undefined; if (id) blocks.push({ id, pos: offset, node, index }); });
  return blocks;
}

export const selectionRoots = (blocks: TreeBlock[], ids: string[]) => { const chosen = new Set(ids); return blocks.filter(block => chosen.has(block.id)); };

export function destinationError(blocks: TreeBlock[], ids: string[], destination: Destination): string | null {
  const roots = selectionRoots(blocks, ids);
  if (!roots.length) return '이동할 블록이나 위치를 찾을 수 없습니다.';
  if (destination.anchorId) {
    const anchor = blocks.find(block => block.id === destination.anchorId);
    if (!anchor) return '이동 위치가 바뀌었습니다. 다시 선택하세요.';
    if (roots.some(root => root.id === anchor.id)) return '선택한 블록 위에는 놓을 수 없습니다.';
  }
  return null;
}

/** 옮기기 한 번은 실행 취소 한 단계다. 지운 뒤의 문서에서 ID로 다시 자리를 찾는다. */
export function blockMove(state: EditorState, ids: string[], destination: Destination): { transaction?: Transaction; ids: string[]; error?: string } {
  const blocks = blockTree(state.doc), roots = selectionRoots(blocks, ids), error = destinationError(blocks, ids, destination);
  if (error) return { ids: roots.map(block => block.id), error };
  let tr = closeHistory(state.tr);
  for (const block of [...roots].reverse()) tr = tr.delete(block.pos, block.pos + block.node.nodeSize);
  const fragment = Fragment.fromArray(roots.map(block => block.node));
  let insert = tr.doc.content.size;
  if (destination.anchorId) {
    const anchor = blockTree(tr.doc).find(block => block.id === destination.anchorId);
    if (!anchor) return { ids: [], error: '이동 위치가 바뀌었습니다.' };
    insert = anchor.pos + (destination.side === 'after' ? anchor.node.nodeSize : 0);
  }
  tr = tr.insert(insert, fragment);
  const first = blockTree(tr.doc).find(block => block.id === roots[0].id);
  if (first) tr = tr.setSelection(TextSelection.near(tr.doc.resolve(first.pos + 1)));
  if (tr.doc.eq(state.doc)) return { ids: roots.map(block => block.id) };
  return { transaction: tr.setMeta('blockMove', true), ids: roots.map(block => block.id) };
}

/** 고른 블록을 한 칸 위(-1)·아래(1)로 옮길 자리. 끝이면 null. */
export function siblingStep(blocks: TreeBlock[], ids: string[], direction: number): Destination | null {
  const indices = selectionRoots(blocks, ids).map(block => blocks.indexOf(block));
  if (!indices.length) return null;
  const next = (direction < 0 ? Math.min(...indices) : Math.max(...indices)) + direction;
  if (next < 0 || next >= blocks.length) return null;
  return { anchorId: blocks[next].id, side: direction < 0 ? 'before' : 'after' };
}

import { useEffect, useRef, useState } from 'react';

export type Scheme = 'light' | 'dark';
/**
 * Mermaid의 색표(밝게 · 어둡게). Mermaid는 CSS 변수를 읽지 못해 실제 색 값을 넘겨야 한다. 파란 회색 면, 진한 글자, 회청색 선으로
 * 가이드 본문의 도표(shared/markdown)와 같다. background는 크게 보기 창에서 도표 아래에 까는 바탕이다.
 */
export const diagramColors = {
  light: { darkMode: false, background: '#fafafa', primaryColor: '#edf2f6', primaryTextColor: '#1f2933', primaryBorderColor: '#7d90a1', lineColor: '#5c6d7c', secondaryColor: '#e3e9ee', tertiaryColor: '#f3f5f7' },
  dark: { darkMode: true, background: '#1c1e21', primaryColor: '#242c34', primaryTextColor: '#e0e7ed', primaryBorderColor: '#52697a', lineColor: '#8a9cab', secondaryColor: '#23292e', tertiaryColor: '#202529' },
} as const;
/** 화면의 색 구성: 테마의 dark 변형과 같이 html[data-theme=dark]로 읽는다. */
export const pageScheme = (): Scheme => document.documentElement.closest('[data-theme=dark]') ? 'dark' : 'light';
function useScheme() {
  const [scheme, setScheme] = useState(pageScheme);
  useEffect(() => {
    const watch = new MutationObserver(() => setScheme(pageScheme()));
    watch.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
    return () => watch.disconnect();
  }, []);
  return scheme;
}

let mermaidModule: Promise<typeof import('mermaid')> | undefined;
// Mermaid의 설정은 전역이라, 도표마다 제 색표를 정하고 그린 뒤에 다음 도표가 제 것을 정한다.
let rendering: Promise<unknown> = Promise.resolve();
async function diagram(source: string, scheme: Scheme) {
  mermaidModule ??= import('mermaid');
  const { default: mermaid } = await mermaidModule;
  const turn = rendering.then(() => {
    mermaid.initialize({ startOnLoad: false, theme: 'base', themeVariables: { ...diagramColors[scheme], fontFamily: 'Pretendard Variable, sans-serif', fontSize: '14px' },
      securityLevel: 'strict', htmlLabels: false, maxTextSize: 30000, maxEdges: 200, suppressErrorRendering: true, flowchart: { htmlLabels: false },
      secure: ['securityLevel', 'startOnLoad', 'maxTextSize', 'maxEdges', 'suppressErrorRendering'] });
    return draw(mermaid, source);
  });
  rendering = turn.catch(() => undefined);
  return turn;
}
async function draw(mermaid: typeof import('mermaid').default, source: string) {
  // 담을 상자를 주지 않으면 Mermaid는 <body> 끝에 상자를 붙여 그 안에서 재므로, 그리는 동안 페이지가 길어지고 스크롤 막대가
  // 깜빡인다. 높이 0의 숨은 고정 상자 안에서 잰다.
  const holder = document.createElement('div');
  holder.setAttribute('aria-hidden', 'true');
  holder.style.cssText = 'position:fixed;left:0;top:0;width:100%;height:0;overflow:hidden;visibility:hidden;pointer-events:none';
  document.body.append(holder);
  const { svg } = await mermaid.render(`diagram-${crypto.randomUUID()}`, source, holder).finally(() => holder.remove());
  const root = new DOMParser().parseFromString(svg, 'image/svg+xml').documentElement as unknown as SVGSVGElement;
  const width = Number(root.getAttribute('viewBox')?.split(/[ ,]+/)[2]);
  // 칸 폭을 채운다(잘리지 않게 비율 유지). 아주 작은 도표가 지나치게 커지지 않게 원래 크기의 3배까지만 키우고, 높이 한도는 CSS가 둔다.
  if (Number.isFinite(width) && width > 0) { root.style.width = '100%'; root.style.maxWidth = `${Math.round(width * 3)}px`; root.style.height = 'auto'; }
  return root.outerHTML;
}

/** 도표 원문을 그린 SVG(html). 화면 색만 바뀌면 새 그림이 준비될 때까지 이전 그림을 둔다. */
export function useDiagram(source: string, isDiagram: boolean) {
  const [state, setState] = useState({ html: '', error: '', pending: isDiagram });
  const scheme = useScheme(), drawn = useRef(source);
  useEffect(() => {
    if (!isDiagram) return;
    let disposed = false;
    const recolour = drawn.current === source;
    drawn.current = source;
    if (!recolour) setState({ html: '', error: '', pending: true });
    const timer = setTimeout(() => {
      void (async () => {
        try {
          if (!source.trim()) throw Error('원문을 입력하세요.');
          if (source.length > 30000) throw Error('원문은 30,000자까지 입력할 수 있습니다.');
          const html = await diagram(source, scheme);
          if (!disposed) setState({ html, error: '', pending: false });
        } catch (error) {
          if (!disposed) setState({ html: '', error: (error instanceof Error ? error.message : '미리보기를 만들지 못했습니다').slice(0, 350), pending: false });
        }
      })();
    }, 150);
    return () => { disposed = true; clearTimeout(timer); };
  }, [source, scheme, isDiagram]);
  return { ...state, scheme };
}

/** 링크 카드의 주소를 검사한다: 로그인 정보가 없는 HTTPS 주소만, 이 화면 자신은 넣지 않는다. */
export function embedURL(source: string): { original: string; host: string } {
  let parsed: URL;
  try { parsed = new URL(source.trim()); } catch { throw Error('https://로 시작하는 웹 주소를 입력하세요.'); }
  if (parsed.protocol !== 'https:' || parsed.username || parsed.password) throw Error('로그인 정보가 없는 HTTPS 주소를 입력하세요.');
  if (typeof location !== 'undefined' && parsed.origin === location.origin) throw Error('현재 문서 편집기 자체는 임베드할 수 없습니다.');
  return { original: parsed.href, host: parsed.hostname.toLowerCase() };
}

import type { Editor } from "@tiptap/react"
import { cn } from "@/shared/lib/utils"
import { COLORS } from "./colors"
import type { MenuEntry } from "./menu"
import type { HeadingLevel } from "./schema"

/**
 * 서식 도구(블록 메뉴 · 선택 서식 도구 · 상단 막대)가 함께 쓰는 것: 블록 종류와 바꾸기, 색 목록, 색 견본, Solar에 없는 그림
 * (줄 정렬 · 들여쓰기 · 위아래 첨자).
 */

/** 서로 바꿀 수 있는 글 블록의 종류. glyph는 메뉴에 보이는 짧은 표시다. */
export const TEXT_BLOCKS = [
  { id: "paragraph", label: "텍스트", glyph: "T" },
  { id: "heading2", label: "제목 2", glyph: "H2" }, { id: "heading3", label: "제목 3", glyph: "H3" }, { id: "heading4", label: "제목 4", glyph: "H4" },
  { id: "bulletList", label: "글머리 목록", glyph: "•" }, { id: "orderedList", label: "번호 목록", glyph: "1." }, { id: "taskList", label: "할 일 목록", glyph: "☑" },
  { id: "blockquote", label: "인용", glyph: "❞" }, { id: "codeBlock", label: "코드", glyph: "</>" },
] as const
export type TextBlockId = typeof TEXT_BLOCKS[number]["id"]

/** 커서가 있는 글 블록의 종류. 목록 · 인용 안의 문단은 그 목록 · 인용으로 본다. */
export function textBlockOf(editor: Editor): TextBlockId {
  if (editor.isActive("heading")) return `heading${editor.getAttributes("heading").level}` as TextBlockId
  for (const id of ["bulletList", "orderedList", "taskList", "blockquote", "codeBlock"] as const) if (editor.isActive(id)) return id
  return "paragraph"
}

/** 고른 글 블록을 다른 종류로 바꾼다. 먼저 목록 · 인용을 풀어 문단으로 만든 뒤(clearNodes) 새 종류를 입힌다. */
export function turnInto(editor: Editor, id: TextBlockId) {
  const chain = editor.chain().focus().clearNodes()
  if (id.startsWith("heading")) return chain.setHeading({ level: Number(id.slice(-1)) as HeadingLevel }).run()
  if (id === "bulletList") return chain.toggleBulletList().run()
  if (id === "orderedList") return chain.toggleOrderedList().run()
  if (id === "taskList") return chain.toggleTaskList().run()
  if (id === "blockquote") return chain.setBlockquote().run()
  if (id === "codeBlock") return chain.setCodeBlock().run()
  return chain.run()
}

const Glyph = ({ text }: { text: string }) => <span aria-hidden className="inline-grid w-4.5 shrink-0 place-items-center text-[0.6875rem] font-semibold tracking-tight">{text}</span>

/** 블록 종류 목록(메뉴 항목). */
export const turnIntoEntries = (current: TextBlockId | undefined, onSelect: (id: TextBlockId) => void): MenuEntry[] => [
  { kind: "title", label: "종류 바꾸기" },
  ...TEXT_BLOCKS.map(block => ({ kind: "item" as const, label: block.label, icon: <Glyph text={block.glyph} />, isChecked: current === block.id, onSelect: () => onSelect(block.id) })),
]

/** 글자색과 배경색 목록(메뉴 항목). 빈 값은 기본(색 없음). */
export const colorEntries = (text: string, background: string, onText: (color: string) => void, onBackground: (color: string) => void): MenuEntry[] => [
  { kind: "title", label: "글자색" },
  ...COLORS.map(color => ({ kind: "item" as const, label: `${color.name} 글자`, icon: <Swatch ink={color.ink} />, isChecked: text === color.ink, onSelect: () => onText(color.ink) })),
  { kind: "separator" },
  { kind: "title", label: "배경색" },
  ...COLORS.map(color => ({ kind: "item" as const, label: `${color.name} 배경`, icon: <Swatch fill={color.fill || "var(--card)"} isRound />, isChecked: background === color.fill,
    onSelect: () => onBackground(color.fill) })),
]

/** 색 견본: 글자색은 A 한 글자, 배경색은 둥근 칸. isFramed는 상단 막대 · 서식 도구의 색 단추처럼 동그라미 안에 A를 둔다. */
export function Swatch({ ink, fill, isRound = false, isFramed = false }: { ink?: string; fill?: string; isRound?: boolean; isFramed?: boolean }) {
  return (
    <span aria-hidden
      className={cn(isRound ? "inline-block size-4 shrink-0 rounded-full border border-input"
        : "inline-grid size-4.5 shrink-0 place-items-center text-sm leading-none font-semibold", isFramed && "size-5.5 rounded-full border border-input text-xs")}
      // check-ui: allow-style 견본마다 다른 색 값(본문에 남는 색 변수)이다.
      style={{ ...(ink ? { color: ink } : {}), ...(fill ? { background: fill } : {}) }}>
      {isRound ? "" : "A"}
    </span>
  )
}

export type Align = "left" | "center" | "right" | "justify"
export const ALIGN_LABELS: Record<Align, string> = { left: "왼쪽 정렬", center: "가운데 정렬", right: "오른쪽 정렬", justify: "양쪽 정렬" }

/** 줄 정렬 그림: 길이가 다른 가로줄 넷을 정렬 방향에 맞춰 놓는다(Solar에 글 정렬 아이콘이 없다). */
export function AlignGlyph({ kind }: { kind: Align }) {
  const widths = kind === "justify" ? [14, 14, 14, 14] : [14, 9, 12, 7]
  return (
    <svg viewBox="0 0 16 16" width="15" height="15" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round">
      {widths.map((width, row) => {
        const start = kind === "center" ? (16 - width) / 2 : kind === "right" ? 15 - width : 1
        return <path key={row} d={`M${start} ${3 + row * 3.3}h${width}`} />
      })}
    </svg>
  )
}

/** 들여쓰기 · 내어쓰기 그림: 줄 셋과 방향 화살표. */
export function IndentGlyph({ isOut = false }: { isOut?: boolean }) {
  return (
    <svg viewBox="0 0 16 16" width="15" height="15" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
      <path d="M7 3h8M7 8h8M7 13h8" /><path d={isOut ? "M4 5.5 1.5 8 4 10.5" : "M1.5 5.5 4 8 1.5 10.5"} />
    </svg>
  )
}

export const Script = ({ isUp }: { isUp: boolean }) => <span aria-hidden className="text-[0.8125rem] leading-none font-semibold">x{isUp ? <sup className="text-[0.5625rem]">2</sup> : <sub className="text-[0.5625rem]">2</sub>}</span>

import { useState, type ReactElement, type ReactNode } from "react"
import { useIsMobile } from "@/shared/lib/use-mobile"
import { cn } from "@/shared/lib/utils"
import { Button } from "@/shared/ui/button"
import { Drawer, DrawerContent, DrawerHeader, DrawerTitle, DrawerTrigger } from "@/shared/ui/drawer"
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuShortcut, DropdownMenuSub, DropdownMenuSubContent,
  DropdownMenuSubTrigger, DropdownMenuTrigger,
} from "@/shared/ui/dropdown-menu"
import { ArrowLeftIcon, CheckIcon, ChevronRightIcon } from "@/shared/ui/icon"
import { Popover, PopoverContent, PopoverTrigger } from "@/shared/ui/popover"
import { EDITOR_COLOR_VARS } from "./colors"

/**
 * 에디터의 떠 있는 메뉴(블록 손잡이 · 서식 도구 · 상단 막대 · 표 · 미디어 너비)가 함께 쓰는 틀. 메뉴는 항목 목록(MenuEntry)으로
 * 넘기고, 데스크톱은 드롭다운(하위 메뉴는 옆으로 펼친다), 휴대폰은 바텀시트(하위 메뉴는 시트 안에서 들어가고 뒤로 온다)로 그린다.
 * 화살표 · Home · End · 글자 찾기 · Esc는 Base UI 메뉴가 맡는다.
 *
 * 메뉴를 닫아도 초점을 여는 단추로 돌리지 않는다(finalFocus={false}). 항목은 대개 본문에 명령을 돌리며 chain().focus()로 본문에
 * 초점을 돌려 두는데, 메뉴가 그 뒤에 단추로 초점을 가져가면 이어서 친 글이 본문에 들어가지 않는다.
 */
export type MenuEntry =
  | { kind: "item"; label: string; icon?: ReactNode; hint?: string; isChecked?: boolean; isDanger?: boolean; isDisabled?: boolean; onSelect: () => void }
  | { kind: "title"; label: string }
  | { kind: "separator" }
  | { kind: "sub"; label: string; icon?: ReactNode; isDisabled?: boolean; entries: MenuEntry[] }

/** 맥에서는 ⌘, 그 밖에서는 Ctrl. 메뉴의 단축키 표기에 쓴다. */
export const MOD = typeof navigator !== "undefined" && /Mac|iPhone|iPad/.test(navigator.platform) ? "⌘" : "Ctrl"

/** 누를 때 본문의 선택이 풀리지 않게 한다(단추가 초점을 가져가지 않는다). */
export const keepSelection = (event: { preventDefault: () => void }) => event.preventDefault()

/** 메뉴 항목 줄 모양: 데스크톱 32px, 휴대폰 48px. 아이콘은 보조 아이콘 색. */
const ROW = "min-h-8 gap-2.5 px-2.5 py-1.5 text-[0.8125rem] [&_svg]:text-icon-muted max-md:min-h-12 max-md:text-sm"
const TITLE = "px-2.5 pt-2 pb-1 text-xs font-semibold text-muted-foreground"

function DesktopEntries({ entries }: { entries: MenuEntry[] }) {
  return entries.map((entry, index) => {
    if (entry.kind === "separator") return <DropdownMenuSeparator key={index} className="mx-1 my-1.5" />
    if (entry.kind === "title") return <div key={index} role="presentation" className={TITLE}>{entry.label}</div>
    if (entry.kind === "sub") {
      return (
        <DropdownMenuSub key={index}>
          <DropdownMenuSubTrigger disabled={entry.isDisabled} className={cn(ROW, "data-disabled:opacity-50")}>
            {entry.icon}<span className="min-w-0 flex-1 truncate">{entry.label}</span>
          </DropdownMenuSubTrigger>
          <DropdownMenuSubContent finalFocus={false} className={cn("max-h-[min(26rem,var(--available-height))] w-56 p-1.5", EDITOR_COLOR_VARS)}>
            <DesktopEntries entries={entry.entries} />
          </DropdownMenuSubContent>
        </DropdownMenuSub>
      )
    }
    return (
      <DropdownMenuItem key={index} disabled={entry.isDisabled} variant={entry.isDanger ? "destructive" : "default"} className={ROW} onClick={entry.onSelect}>
        {entry.icon}
        <span className="min-w-0 flex-1 truncate">{entry.label}</span>
        {entry.hint ? <DropdownMenuShortcut className="max-w-32 truncate tracking-normal">{entry.hint}</DropdownMenuShortcut> : null}
        {entry.isChecked ? <CheckIcon className="ml-auto" /> : null}
      </DropdownMenuItem>
    )
  })
}

/** 휴대폰 시트의 항목: 48px 단추 줄. 하위 메뉴는 그 목록으로 들어간다. */
function SheetEntries({ entries, onPick, onEnter }: { entries: MenuEntry[]; onPick: (entry: Extract<MenuEntry, { kind: "item" }>) => void; onEnter: (entry: Extract<MenuEntry, { kind: "sub" }>) => void }) {
  return entries.map((entry, index) => {
    if (entry.kind === "separator") return <div key={index} role="separator" className="mx-1 my-1.5 h-px bg-border" />
    if (entry.kind === "title") return <div key={index} className={TITLE}>{entry.label}</div>
    const isSub = entry.kind === "sub"
    return (
      <Button key={index} variant="ghost" disabled={entry.isDisabled} aria-pressed={!isSub && entry.isChecked ? true : undefined}
        className={cn("h-auto w-full justify-start rounded-lg font-normal", ROW, !isSub && entry.isDanger && "text-destructive [&_svg]:text-destructive")}
        onClick={() => isSub ? onEnter(entry) : onPick(entry)}>
        {entry.icon}
        <span className="min-w-0 flex-1 truncate text-left">{entry.label}</span>
        {isSub ? <ChevronRightIcon /> : entry.isChecked ? <CheckIcon /> : entry.hint ? <span className="text-xs text-muted-foreground">{entry.hint}</span> : null}
      </Button>
    )
  })
}

/**
 * 메뉴 하나. trigger가 여는 단추이고 open은 부르는 쪽이 쥔다(블록 손잡이처럼 누르기를 스스로 다루는 단추는 onOpenChange의 열기를
 * 무시하고 닫기만 받는다). side · align은 데스크톱 드롭다운의 자리다.
 */
export function EditorMenu({ label, trigger, entries, open, onOpenChange, side = "bottom", align = "start", className }: {
  /** 메뉴의 읽기용 이름이자 휴대폰 시트의 제목. */
  label: string
  trigger: ReactElement
  entries: MenuEntry[]
  open: boolean
  onOpenChange: (open: boolean) => void
  side?: "top" | "bottom" | "left" | "right"
  align?: "start" | "center" | "end"
  /** 데스크톱 드롭다운의 너비 등. */
  className?: string
}) {
  const isMobile = useIsMobile()
  const [inside, setInside] = useState<Extract<MenuEntry, { kind: "sub" }> | null>(null)
  if (isMobile) {
    const change = (next: boolean) => { if (!next) setInside(null); onOpenChange(next) }
    return (
      <Drawer open={open} onOpenChange={change}>
        <DrawerTrigger render={trigger} />
        <DrawerContent finalFocus={false} className={EDITOR_COLOR_VARS}>
          <DrawerHeader className="flex-row items-center gap-1 pb-1 text-left">
            {inside ? <Button variant="ghost" size="icon" aria-label="뒤로" className="-ml-2 size-11" onClick={() => setInside(null)}><ArrowLeftIcon /></Button> : null}
            <DrawerTitle>{inside?.label ?? label}</DrawerTitle>
          </DrawerHeader>
          <div role="menu" aria-label={inside?.label ?? label} className="flex min-h-0 flex-col gap-0.5 overflow-y-auto px-3 pt-2 pb-6">
            <SheetEntries entries={inside?.entries ?? entries} onEnter={setInside}
              onPick={entry => { change(false); entry.onSelect() }} />
          </div>
        </DrawerContent>
      </Drawer>
    )
  }
  return (
    <DropdownMenu open={open} onOpenChange={next => onOpenChange(next)} modal={false}>
      <DropdownMenuTrigger render={trigger} />
      <DropdownMenuContent side={side} align={align} finalFocus={false} aria-label={label}
        className={cn("max-h-[min(30rem,var(--available-height))] w-60 p-1.5", EDITOR_COLOR_VARS, className)}>
        <DesktopEntries entries={entries} />
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

/**
 * 입력 칸이 있는 떠 있는 판(링크 입력). 데스크톱 팝오버, 휴대폰 바텀시트. 메뉴처럼 닫을 때 초점을 단추로 돌리지 않는다.
 */
export function EditorPopover({ label, trigger, open, onOpenChange, align = "start", className, children }: {
  label: string; trigger: ReactElement; open: boolean; onOpenChange: (open: boolean) => void; align?: "start" | "center" | "end"
  className?: string; children: ReactNode
}) {
  const isMobile = useIsMobile()
  if (isMobile) {
    return (
      <Drawer open={open} onOpenChange={onOpenChange}>
        <DrawerTrigger render={trigger} />
        <DrawerContent finalFocus={false}>
          <DrawerHeader className="pb-1 text-left"><DrawerTitle>{label}</DrawerTitle></DrawerHeader>
          <div className="flex min-h-0 flex-col gap-1 overflow-y-auto px-3 pt-2 pb-6">{children}</div>
        </DrawerContent>
      </Drawer>
    )
  }
  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverTrigger render={trigger} />
      <PopoverContent align={align} finalFocus={false} aria-label={label} className={cn("w-88 max-w-[calc(100vw-1.5rem)] gap-1 p-1.5", className)}>{children}</PopoverContent>
    </Popover>
  )
}

import { Extension, Node, mergeAttributes, type AnyExtension, type Editor, type JSONContent } from '@tiptap/core';
import Highlight from '@tiptap/extension-highlight';
import { TaskItem, TaskList } from '@tiptap/extension-list';
import Subscript from '@tiptap/extension-subscript';
import Superscript from '@tiptap/extension-superscript';
import { Table, TableKit, TableView } from '@tiptap/extension-table';
import TextAlign from '@tiptap/extension-text-align';
import { TextStyleKit } from '@tiptap/extension-text-style';
import { Plugin } from '@tiptap/pm/state';
import { columnResizing } from '@tiptap/pm/tables';
import StarterKit from '@tiptap/starter-kit';
import { GlobeIcon, HeadingIcon, ListChecksIcon, ListIcon, ListOrderedIcon, MinusIcon, PaperclipIcon, PilcrowIcon, QuoteIcon, SquareCodeIcon, StructureIcon, TableIcon, type Icon } from '@/shared/ui/icon';
import { UploadZone } from './upload-zone';

/** 본문 제목은 2단계부터다. 화면에는 늘 시스템 제목(1단계) 하나가 있다. */
export const HEADING_LEVELS = [2, 3, 4] as const;
export type HeadingLevel = typeof HEADING_LEVELS[number];

/** 블록마다 안정 ID(blockId)를 두는 노드. 블록 메뉴·블록 링크(#block-…)·끌어 옮기기가 이 ID로 블록을 찾는다. */
const BLOCK_TYPES = ['paragraph', 'heading', 'blockquote', 'bulletList', 'orderedList', 'taskList', 'codeBlock', 'horizontalRule', 'table',
  'media', 'mermaidBlock', 'webEmbed'];

export const blank: JSONContent = { type: 'doc', content: [{ type: 'paragraph' }] };

/** 처음 여는 본문을 다듬는다: 빠지거나 겹친 blockId를 채우고, 예전 본문의 1단계 제목은 2단계로 내린다. */
export function prepareDocument(value: JSONContent | undefined): JSONContent {
  const copy: JSONContent = structuredClone(value?.type === 'doc' ? value : blank);
  const seen = new Set<string>();
  const walk = (node: JSONContent) => {
    if (node.type && BLOCK_TYPES.includes(node.type)) {
      node.attrs ??= {};
      if (!node.attrs.blockId || seen.has(node.attrs.blockId)) node.attrs.blockId = crypto.randomUUID();
      seen.add(node.attrs.blockId);
    }
    if (node.type === 'heading' && !HEADING_LEVELS.includes(node.attrs?.level)) node.attrs = { ...node.attrs, level: 2 };
    node.content?.forEach(walk);
  };
  walk(copy);
  if (!copy.content?.length) copy.content = [{ type: 'paragraph' }];
  return copy;
}

/** 내려받거나 그릴 수 있는 주소: 앱 안의 주소, HTTPS, 호스트가 수명을 맡는 blob. 그 밖은 빈 글. */
export const safeSource = (value: unknown) => /^(\/(?!\/)|https:\/\/|blob:)/.test(String(value)) ? String(value) : '';

/** 사진·동영상·오디오·파일 블록. 사진은 올릴 때 잰 대표색과 원본 가로·세로를 함께 둔다. */
export const Media = Node.create({
  name: 'media', group: 'block', atom: true, draggable: true,
  addAttributes() {
    return {
      src: { default: '', parseHTML: element => element.getAttribute('data-src') ?? '' },
      name: { default: '첨부 파일', parseHTML: element => element.getAttribute('data-name') ?? '첨부 파일' },
      mime: { default: 'application/octet-stream', parseHTML: element => element.getAttribute('data-mime') ?? 'application/octet-stream' },
      width: { default: 100, parseHTML: element => Number(element.getAttribute('data-width')) || 100 },
      size: { default: 0, parseHTML: element => Number(element.getAttribute('data-size')) || 0 },
      color: { default: null, parseHTML: element => element.getAttribute('data-color') },
      pixelWidth: { default: null, parseHTML: element => Number(element.getAttribute('data-pixel-width')) || null },
      pixelHeight: { default: null, parseHTML: element => Number(element.getAttribute('data-pixel-height')) || null },
    };
  },
  parseHTML: () => [{ tag: 'figure[data-media]' }],
  renderHTML: ({ HTMLAttributes: a }) => {
    const src = safeSource(a.src), mime = String(a.mime);
    const child = mime.startsWith('image/') ? ['img', { src, alt: a.name, loading: 'lazy' }]
      : mime.startsWith('video/') ? ['video', { src, controls: '', preload: 'metadata' }]
        : mime.startsWith('audio/') ? ['audio', { src, controls: '', preload: 'metadata' }] : ['a', { href: src, download: a.name }, a.name];
    return ['figure', mergeAttributes({ 'data-media': '', 'data-name': a.name, 'data-mime': mime, 'data-src': src, 'data-width': a.width, 'data-size': a.size },
      a.color ? { 'data-color': a.color } : {}, a.pixelWidth && a.pixelHeight ? { 'data-pixel-width': a.pixelWidth, 'data-pixel-height': a.pixelHeight } : {},
      a.blockId ? { 'data-block-id': a.blockId } : {}), child];
  },
});

/** 원문(source) 하나로 그리는 블록: Mermaid 도표와 링크 카드(웹 주소). */
export type SourceKind = 'mermaidBlock' | 'webEmbed';
export const SOURCE_EXAMPLES: Record<SourceKind, string> = { mermaidBlock: 'flowchart LR\n  A[생각] --> B[문서]\n  B --> C[공유]', webEmbed: '' };
export const sourceNode = (kind: SourceKind) => Node.create({
  name: kind, group: 'block', atom: true, selectable: true, draggable: true,
  addAttributes() {
    return { source: { default: SOURCE_EXAMPLES[kind], parseHTML: element => element.getAttribute('data-source') ?? element.textContent ?? '',
      renderHTML: attrs => ({ 'data-source': attrs.source }) } };
  },
  parseHTML: () => [{ tag: `figure[data-rich-type="${kind}"]` }],
  renderHTML: ({ HTMLAttributes }) => ['figure', mergeAttributes(HTMLAttributes, { 'data-rich-type': kind }), ['pre', {}, String(HTMLAttributes['data-source'] ?? '')]],
});

/** 블록 ID를 채우고, 복사·붙여넣기로 겹친 ID는 새로 준다(실행 취소 단계에 넣지 않는다). */
const BlockIdentity = Extension.create({
  name: 'blockIdentity',
  addGlobalAttributes() {
    return [{ types: BLOCK_TYPES, attributes: { blockId: { default: null, parseHTML: element => element.getAttribute('data-block-id'),
      renderHTML: attrs => attrs.blockId ? { 'data-block-id': attrs.blockId } : {} } } }];
  },
  addProseMirrorPlugins() {
    return [new Plugin({ appendTransaction: (transactions, _old, state) => {
      if (!transactions.some(tr => tr.docChanged)) return null;
      const seen = new Set<string>();
      let tr = state.tr;
      state.doc.descendants((node, pos) => {
        if (!('blockId' in node.attrs)) return;
        const id = node.attrs.blockId as string | null;
        if (!id || seen.has(id)) { const next = crypto.randomUUID(); tr = tr.setNodeMarkup(pos, undefined, { ...node.attrs, blockId: next }); seen.add(next); }
        else seen.add(id);
      });
      return tr.docChanged ? tr.setMeta('addToHistory', false) : null;
    } })];
  },
});

/** 너비가 없어진 열의 <col>에서 옛 너비를 지운다. Tiptap의 TableView는 너비를 쓰기만 해서, 너비 조절을 실행 취소해도 화면의 열이 그대로였다. */
class SyncedTableView extends TableView {
  update(node: Parameters<TableView['update']>[0]) {
    if (!super.update(node)) return false;
    let index = 0;
    node.firstChild?.forEach(cell => {
      const widths = cell.attrs.colwidth as number[] | null;
      for (let span = 0; span < (cell.attrs.colspan || 1); span++, index++) {
        const col = this.colgroup.children[index] as HTMLElement | undefined;
        if (col && !widths?.[span]) col.style.removeProperty('width');
      }
    });
    return true;
  }
}

/**
 * 열 경계를 끌어 너비를 바꾸는 표. Tiptap의 표는 에디터가 만들어지는 순간 편집할 수 있을 때만 열 너비 조절을 붙이는데,
 * 본문은 읽기로 열렸다가 편집으로 바뀔 수 있어 그대로 두면 한 번도 붙지 않는다. 그래서 늘 붙여 두고, 읽는 동안에는 조절
 * 기능이 스스로 쉰다(prosemirror-tables가 view.editable을 확인한다).
 */
const ResizableTable = Table.extend({
  addProseMirrorPlugins() {
    const base = this.parent?.() ?? [];
    if (!this.options.resizable || this.editor.isEditable) return base;
    return [columnResizing({ handleWidth: this.options.handleWidth, cellMinWidth: this.options.cellMinWidth, defaultCellMinWidth: this.options.cellMinWidth,
      View: this.options.View, lastColumnResizable: this.options.lastColumnResizable }), ...base];
  },
  addNodeView() { return this.options.resizable ? null : this.parent?.() ?? null; },
});

/** 본문 칸의 확장 묶음. 노드 뷰(사진·도표·링크 카드)는 RichEditor가 넘긴다. */
export function editorExtensions(nodeViews: AnyExtension[]): AnyExtension[] {
  return [
    StarterKit.configure({ heading: { levels: [...HEADING_LEVELS] },
      link: { openOnClick: false, defaultProtocol: 'https', HTMLAttributes: { rel: 'noopener noreferrer', target: '_blank' } } }),
    TableKit.configure({ table: false }), ResizableTable.configure({ resizable: true, cellMinWidth: 120, View: SyncedTableView }),
    TaskList, TaskItem.configure({ nested: true }), TextStyleKit, Highlight.configure({ multicolor: true }), TextAlign.configure({ types: ['heading', 'paragraph'] }),
    Subscript, Superscript, UploadZone, ...nodeViews, BlockIdentity,
  ];
}

export type CommandId = 'paragraph' | `heading${HeadingLevel}` | 'bulletList' | 'orderedList' | 'taskList' | 'blockquote' | 'table' | 'horizontalRule'
  | 'codeBlock' | 'mermaidBlock' | 'html' | 'webEmbed' | 'file';
export type BlockCommand = { id: CommandId; label: string; group: string; hint: string };
const HEADING_HINTS: Record<HeadingLevel, string> = { 2: '큰 구획 제목', 3: '중간 제목', 4: '작은 제목' };

/** 블록 명령의 아이콘. `/` 목록과 상단 서식 막대의 넣기 메뉴가 같이 쓴다. */
export const COMMAND_ICONS: Record<CommandId, Icon> = { paragraph: PilcrowIcon, heading2: HeadingIcon, heading3: HeadingIcon, heading4: HeadingIcon, bulletList: ListIcon,
  orderedList: ListOrderedIcon, taskList: ListChecksIcon, blockquote: QuoteIcon, table: TableIcon, horizontalRule: MinusIcon, codeBlock: SquareCodeIcon, mermaidBlock: StructureIcon,
  html: SquareCodeIcon, webEmbed: GlobeIcon, file: PaperclipIcon };

/** `/` 목록. 묶음 순서대로 보인다. */
export const COMMANDS: BlockCommand[] = [
  { id: 'paragraph', label: '텍스트', group: '기본 블록', hint: '일반 텍스트로 작성' },
  ...HEADING_LEVELS.map(level => ({ id: `heading${level}` as const, label: `제목 ${level}`, group: '기본 블록', hint: HEADING_HINTS[level] })),
  { id: 'bulletList', label: '글머리 기호 목록', group: '기본 블록', hint: '순서 없는 목록' },
  { id: 'orderedList', label: '번호 매기기 목록', group: '기본 블록', hint: '순서 있는 목록' },
  { id: 'taskList', label: '할 일 목록', group: '기본 블록', hint: '완료를 표시하는 체크리스트' },
  { id: 'blockquote', label: '인용', group: '기본 블록', hint: '다른 목소리를 인용' },
  { id: 'table', label: '표', group: '기본 블록', hint: '행과 열로 정리' },
  { id: 'horizontalRule', label: '구분선', group: '기본 블록', hint: '내용 사이의 경계' },
  { id: 'codeBlock', label: '코드', group: '기본 블록', hint: '코드와 서식 없는 텍스트' },
  { id: 'mermaidBlock', label: 'Mermaid 다이어그램', group: '고급 블록', hint: '흐름도·시퀀스·관계도' },
  { id: 'html', label: 'HTML 임베드', group: '미디어', hint: 'HTML 파일을 본문에 미리보기로' },
  { id: 'webEmbed', label: '링크 카드', group: '미디어', hint: '웹 주소를 제목·설명·사진 카드로' },
  { id: 'file', label: '이미지 · 동영상 · 오디오 · 파일', group: '미디어', hint: '최대 10MB' },
];

/** `/` 명령으로 블록을 넣는다. 파일·HTML 임베드는 RichEditor가 올리는 칸을 띄운다. */
export function insertBlock(editor: Editor, id: CommandId, range?: { from: number; to: number }) {
  if (range) editor.chain().focus().deleteRange(range).run();
  const chain = editor.chain().focus();
  if (id === 'mermaidBlock' || id === 'webEmbed') return chain.insertContent({ type: id }).run();
  if (id === 'paragraph') return chain.setParagraph().run();
  if (id.startsWith('heading')) return chain.setHeading({ level: Number(id.slice(-1)) as HeadingLevel }).run();
  if (id === 'bulletList') return chain.toggleBulletList().run();
  if (id === 'orderedList') return chain.toggleOrderedList().run();
  if (id === 'taskList') return chain.toggleTaskList().run();
  if (id === 'blockquote') return chain.toggleBlockquote().run();
  if (id === 'codeBlock') return chain.toggleCodeBlock().run();
  if (id === 'horizontalRule') return chain.setHorizontalRule().run();
  if (id === 'table') return chain.insertTable({ rows: 3, cols: 3, withHeaderRow: true }).run();
  return false;
}

import type { ComponentProps, ReactElement } from "react"
import { cn } from "@/shared/lib/utils"
import { Button } from "@/shared/ui/button"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/shared/ui/tooltip"

/**
 * 서식 막대 · 선택 서식 도구의 단추. 데스크톱 28px(넓은 단추는 글자와 ▼), 휴대폰 44px. 켜진 서식은 aria-pressed로 한 단계
 * 진한 바탕이다. 이름은 툴팁으로 보인다(단축키가 있으면 함께).
 */
const TOOL = "text-icon-muted hover:text-foreground aria-expanded:text-foreground aria-pressed:bg-pressed aria-pressed:text-foreground max-md:size-11"

/**
 * 툴팁을 단 단추. 메뉴의 여는 단추로도 쓴다: 메뉴가 넘기는 속성(ref · 누르기 · aria-*)을 그대로 단추에 잇는다.
 */
export function Tip({ label, children, ...props }: { label: string; children: ReactElement } & Record<string, unknown>) {
  return (
    <Tooltip>
      <TooltipTrigger render={children} {...props} />
      <TooltipContent className="max-md:hidden">{label}</TooltipContent>
    </Tooltip>
  )
}

export function ToolButton({ label, tip, isWide = false, className, ...props }: ComponentProps<typeof Button> & {
  /** 읽기용 이름. tip이 없으면 툴팁도 이 이름이다. */
  label: string
  tip?: string
  /** 아이콘만이 아니라 글자 · ▼가 함께 있는 단추. */
  isWide?: boolean
}) {
  return (
    <Tip label={tip ?? label}>
      <Button variant="ghost" size={isWide ? "sm" : "icon-sm"} aria-label={label}
        className={cn(TOOL, isWide && "gap-1 px-2 text-foreground max-md:w-auto max-md:px-3", className)} {...props} />
    </Tip>
  )
}

/** 도구 묶음 사이의 가는 세로줄. */
export const ToolDivider = () => <span aria-hidden className="mx-1 inline-block h-4.5 w-px shrink-0 bg-border" />

/**
 * 본문 칸이 호스트에게 받는 것. 키트에는 서버가 없으므로 올리기·링크 미리보기는 호스트의 비동기 함수가 맡는다.
 */

/** 올린 파일. 사진이면 올릴 때 잰 대표색(#rrggbb)과 원본 가로·세로를 함께 주면 다시 열 때 자리를 먼저 그 색·비율로 잡는다. */
export type UploadedFile = { url: string; name: string; mime: string; size?: number; dominantColor?: string; width?: number; height?: number };
/** 파일 하나를 올린다. 진행률(0~100)을 알리고, 취소 신호를 받는다. url은 앱 안의 주소, HTTPS, 또는 호스트가 수명을 맡는 blob URL이다. */
export type UploadFile = (file: File, progress?: (percent: number) => void, signal?: AbortSignal) => Promise<UploadedFile>;

/** 링크 입력 칸에서 이름으로 찾아 걸 수 있는 것(같은 공간의 문서): 이름, 앱 안의 주소(/…), 덧붙이는 설명. */
export type LinkChoice = { title: string; href: string; hint?: string };

/** 링크 카드가 보일 그 페이지의 제목·설명·대표 사진. 읽지 못한 값은 비운다. */
export type LinkPreview = { url: string; site?: string; title?: string; description?: string; image?: string };
/** 웹 주소의 미리보기를 읽는다. 서버가 읽어야 한다(브라우저가 남의 사이트에 직접 묻지 않는다). 실패하면 주소만 있는 카드가 된다. */
export type ReadLinkPreview = (url: string) => Promise<LinkPreview>;

import { Extension } from "@tiptap/core"
import { Plugin, PluginKey, type EditorState } from "@tiptap/pm/state"
import { Decoration, DecorationSet, type EditorView } from "@tiptap/pm/view"
import { useState } from "react"
import { createRoot } from "react-dom/client"
import { cn } from "@/shared/lib/utils"
import { Button } from "@/shared/ui/button"
import { UploadIcon, XIcon } from "@/shared/ui/icon"

/**
 * 파일을 올릴 자리. `/` 명령의 파일이나 HTML 임베드를 고르면 본문의 그 자리에 점선 칸이 뜬다(HTML 칸은 .html만 고르게 한다).
 * 누르면 파일 고르기가 열리고, 파일을 끌어다 놓아도 된다. 칸은 문서에 저장되지 않는 화면 표시(decoration)라서 파일을 올리지
 * 않고 닫아도 본문에 남는 것이 없다. 파일이 올라가기 시작하면 칸은 닫히고 그 자리에 파일 블록이 들어간다.
 */
export type UploadZoneKind = "file" | "html"
type ZoneState = { pos: number | null; kind: UploadZoneKind }
type Storage = { pick: (kind: UploadZoneKind) => void }
export const uploadZoneKey = new PluginKey<ZoneState>("uploadZone")

/** 칸이 열려 있는 문서 위치. 닫혀 있으면 null. */
export const uploadZonePos = (state: EditorState) => uploadZoneKey.getState(state)?.pos ?? null
export const closeUploadZone = (view: EditorView) => {
  if (uploadZonePos(view.state) !== null) view.dispatch(view.state.tr.setMeta(uploadZoneKey, { pos: null, kind: "file" }))
}
/** 커서가 있는 블록 자리에 칸을 연다: 빈 줄이면 그 줄 앞에, 글이 있으면 그 블록 뒤에. */
export function openUploadZone(view: EditorView, kind: UploadZoneKind = "file") {
  const { $from } = view.state.selection
  const isEmptyLine = $from.parent.isTextblock && $from.parent.content.size === 0
  const pos = $from.depth ? (isEmptyLine ? $from.before() : $from.after()) : $from.pos
  view.dispatch(view.state.tr.setMeta(uploadZoneKey, { pos, kind }))
}

const WORDS: Record<UploadZoneKind, [pick: string, hint: string]> = {
  html: ["HTML 파일을 눌러서 올리기", "HTML 파일(.html) 하나에 최대 10MB · 본문에 미리보기로 들어갑니다"],
  file: ["눌러서 올리기", "사진 · 동영상 · 오디오 · 파일, 하나에 최대 10MB"],
}

/** 점선 칸 모양. 링크 카드의 주소 넣는 칸(SourceView)도 같은 모양을 쓴다. */
export const ZONE = "relative my-5 rounded-xl border-[1.5px] border-dashed border-input bg-accent transition-colors hover:border-ring hover:bg-pressed data-over:border-ring data-over:bg-pressed"
export const ZONE_ART = "grid size-11 flex-none place-items-center rounded-full bg-primary text-primary-foreground [&_svg]:size-5.5"

/** 칸의 내용. 끌어 온 동안의 표시만 맡고, 놓은 파일을 올리는 일은 에디터 틀이 한다(RichEditor의 onDropCapture). */
function Zone({ kind, onPick, onClose }: { kind: UploadZoneKind; onPick: () => void; onClose: () => void }) {
  const [isOver, setOver] = useState(false)
  const [pick, hint] = WORDS[kind]
  return (
    <div role="group" aria-label={kind === "html" ? "HTML 파일 올리는 칸" : "파일 올리는 칸"} data-over={isOver || undefined} className={ZONE}
      onKeyDown={event => { if (event.key === "Escape") { event.preventDefault(); onClose() } }}
      onDragOver={event => { if (event.dataTransfer.types.includes("Files")) { event.preventDefault(); setOver(true) } }}
      onDragLeave={() => setOver(false)} onDrop={() => setOver(false)}>
      <button type="button" onClick={onPick}
        className="flex w-full cursor-pointer flex-col items-center gap-2 rounded-[inherit] px-4 py-9 text-sm text-foreground outline-none focus-visible:ring-3 focus-visible:ring-ring/50">
        <span className={ZONE_ART}><UploadIcon /></span>
        <span><u>{pick}</u> 또는 끌어다 놓기</span>
        <span className="text-xs text-muted-foreground">{hint}</span>
      </button>
      <Button variant="ghost" size="icon-sm" aria-label="올리는 칸 닫기" title="닫기" className={cn("absolute top-2 right-2 text-icon-muted max-md:size-11")} onClick={onClose}>
        <XIcon />
      </Button>
    </div>
  )
}

/**
 * 칸은 ProseMirror의 위젯이라 React 트리 바깥의 DOM이다. 그 DOM에 따로 React 뿌리를 두어 키트 부품으로 그리고, 위젯이 빠지면 거둔다.
 * (거두기는 다음 틈에 한다: 위젯은 React가 그리는 도중에 빠질 수 있고, 그때 바로 거두면 React가 경고한다.)
 */
function zone(view: EditorView, storage: Storage, kind: UploadZoneKind) {
  const box = document.createElement("div")
  box.contentEditable = "false"
  const root = createRoot(box)
  const close = () => { closeUploadZone(view); view.focus() }
  root.render(<Zone kind={kind} onPick={() => storage.pick(kind)} onClose={close} />)
  return Object.assign(box, { unmountZone: () => queueMicrotask(() => root.unmount()) })
}

export const UploadZone = Extension.create<Record<string, never>, Storage>({
  name: "uploadZone",
  addStorage() { return { pick: () => undefined } },
  addProseMirrorPlugins() {
    const storage = this.storage
    return [new Plugin<ZoneState>({
      key: uploadZoneKey,
      state: {
        init: () => ({ pos: null, kind: "file" }),
        apply(tr, value) {
          const meta = tr.getMeta(uploadZoneKey) as ZoneState | undefined
          if (meta) return meta
          return value.pos === null ? value : { ...value, pos: tr.mapping.map(value.pos) }
        },
      },
      props: {
        decorations(state) {
          const { pos, kind } = uploadZoneKey.getState(state)!
          return pos === null ? null : DecorationSet.create(state.doc, [Decoration.widget(pos, view => zone(view, storage, kind),
            { side: -1, key: `upload-zone-${kind}`, stopEvent: () => true, ignoreSelection: true,
              destroy: node => (node as HTMLElement & { unmountZone?: () => void }).unmountZone?.() })])
        },
      },
    })]
  },
})

import { closeHistory } from "@tiptap/pm/history"
import { NodeSelection, type SelectionBookmark, type Transaction } from "@tiptap/pm/state"
import type { Editor } from "@tiptap/react"
import { useEffect, useRef, useState } from "react"
import { Button } from "@/shared/ui/button"
import { PaperclipIcon, RefreshCwIcon, XIcon } from "@/shared/ui/icon"
import { Progress } from "@/shared/ui/progress"
import type { UploadFile } from "./types"

type Job = { id: string; batch: string; file: File; state: "queued" | "uploading" | "failed"; progress: number; error: string; controller: AbortController; bookmark: SelectionBookmark }

/**
 * 올리기 줄: 고른 파일을 하나씩 올리고, 다 올라가면 고를 때의 자리에 파일 블록을 넣는다. 진행 · 실패 · 다시 시도 · 취소를 본문 위
 * 줄에 보인다. 올리는 동안 창을 닫으려 하면 브라우저가 묻는다.
 */
export function useUploads(editor: Editor | null, upload: UploadFile) {
  const pipeline = useRef(Promise.resolve())
  const jobs = useRef(new Map<string, Job>()), alive = useRef(true), [, refresh] = useState(0)
  const draw = () => { if (alive.current) refresh(n => n + 1) }
  useEffect(() => {
    alive.current = true
    if (!editor) return
    const map = ({ transaction }: { transaction: Transaction }) => { for (const job of jobs.current.values()) job.bookmark = job.bookmark.map(transaction.mapping) }
    const before = (event: BeforeUnloadEvent) => { if ([...jobs.current.values()].some(job => job.state !== "failed")) event.preventDefault() }
    editor.on("transaction", map); window.addEventListener("beforeunload", before)
    return () => {
      alive.current = false
      for (const job of jobs.current.values()) job.controller.abort()
      jobs.current.clear(); editor.off("transaction", map); window.removeEventListener("beforeunload", before)
    }
  }, [editor])
  async function run(job: Job) {
    if (!editor || editor.isDestroyed || !alive.current || !jobs.current.has(job.id)) return
    job.state = "uploading"; job.progress = 0; job.error = ""; job.controller = new AbortController(); draw()
    try {
      const asset = await upload(job.file, value => { job.progress = value; draw() }, job.controller.signal)
      if (!alive.current || editor.isDestroyed || !jobs.current.has(job.id)) return
      const position = job.bookmark.resolve(editor.state.doc).to, blockId = crypto.randomUUID()
      editor.view.dispatch(closeHistory(editor.state.tr))
      editor.commands.insertContentAt(position, { type: "media", attrs: { blockId, src: asset.url, name: asset.name, mime: asset.mime, size: asset.size ?? job.file.size,
        width: 100, color: asset.dominantColor ?? null, pixelWidth: asset.width ?? null, pixelHeight: asset.height ?? null } }, { updateSelection: false })
      editor.view.dispatch(closeHistory(editor.state.tr))
      // 같이 고른 다음 파일은 방금 넣은 블록 뒤에 이어 놓는다.
      let inserted: number | undefined
      editor.state.doc.descendants((node, pos) => { if (node.attrs.blockId === blockId) inserted = pos })
      if (inserted !== undefined) for (const next of jobs.current.values()) if (next.batch === job.batch && next.state === "queued") next.bookmark = NodeSelection.create(editor.state.doc, inserted).getBookmark()
      jobs.current.delete(job.id)
    } catch (error) {
      if ((error as Error).name === "AbortError") jobs.current.delete(job.id)
      else { job.state = "failed"; job.error = error instanceof Error ? error.message : "업로드하지 못했습니다" }
    }
    draw()
  }
  function enqueue(files: File[]) {
    if (!editor || !editor.isEditable) return
    const batch = crypto.randomUUID()
    for (const file of files) {
      const job: Job = { id: crypto.randomUUID(), batch, file, state: "queued", progress: 0, error: "", controller: new AbortController(), bookmark: editor.state.selection.getBookmark() }
      jobs.current.set(job.id, job)
      pipeline.current = pipeline.current.then(() => run(job))
      draw()
    }
  }
  const panel = jobs.current.size > 0 ? (
    <section aria-label="파일 업로드" className="mb-5 flex flex-col divide-y overflow-hidden rounded-lg border bg-card">
      {[...jobs.current.values()].map(job => (
        <div key={job.id} className="flex items-center gap-3 px-3.5 py-3">
          <PaperclipIcon className="text-icon-muted" />
          <div className="flex min-w-0 flex-1 flex-col gap-1">
            <span className="truncate text-sm font-medium">{job.file.name}</span>
            {job.state !== "failed" ? <>
              <span role="status" className="text-xs text-muted-foreground">{job.state === "queued" ? "업로드 대기 중…" : job.progress === 100 ? "보관하는 중…" : `업로드 중 · ${job.progress}%`}</span>
              <Progress value={job.progress} aria-label={`${job.file.name} 업로드 진행`} />
            </> : <span role="alert" className="text-xs text-destructive">{job.error}</span>}
          </div>
          {job.state === "failed" ? (
            <Button variant="ghost" size="sm" aria-label={`${job.file.name} 다시 업로드`} className="max-md:h-11"
              onClick={() => { job.state = "queued"; pipeline.current = pipeline.current.then(() => run(job)); draw() }}>
              <RefreshCwIcon data-icon="inline-start" />재시도
            </Button>
          ) : null}
          <Button variant="ghost" size="icon-sm" aria-label={`${job.file.name} ${job.state !== "failed" ? "업로드 취소" : "업로드 닫기"}`} className="max-md:size-11"
            onClick={() => { job.controller.abort(); jobs.current.delete(job.id); draw() }}>
            <XIcon />
          </Button>
        </div>
      ))}
    </section>
  ) : null
  return { enqueue, panel, hasPending: jobs.current.size > 0 }
}

import { createContext, lazy, Suspense, useContext } from "react"
import type { Slide } from "yet-another-react-lightbox"
import { Button } from "@/shared/ui/button"
import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog"
import type { LinkPreview, ReadLinkPreview } from "./types"

/** 크게 볼 도표: 그린 SVG 그대로(웹 글꼴과 색표 유지), 원래 크기와 바탕색과 함께. */
export type DiagramSlide = { type: "diagram"; svg: string; width: number; height: number; label: string; background: string }
declare module "yet-another-react-lightbox" { interface SlideTypes { diagram: DiagramSlide } }
export type ZoomSlide = Slide | DiagramSlide
/** 크게 볼 HTML 파일: 본문에 넣은 HTML 임베드의 주소와 이름. */
export type HtmlPage = { src: string; title: string }

/**
 * 노드 뷰(사진 · 도표 · 링크 카드)가 에디터 바깥의 것에 닿는 길: 크게 보기 창을 열고, 링크 미리보기를 읽는다. RichEditor가 둔다.
 */
export type EditorHost = { openZoom: (slide: ZoomSlide) => void; openHtml: (page: HtmlPage) => void; readPreview?: ReadLinkPreview }
export const EditorHostContext = createContext<EditorHost>({ openZoom: () => undefined, openHtml: () => undefined })
export const useEditorHost = () => useContext(EditorHostContext)

/** 그린 Mermaid SVG를 크게 보기 슬라이드로: viewBox에서 원래 크기를 읽는다. 크기를 모르면 null. */
export function diagramSlide(svg: SVGSVGElement | null | undefined, background: string, label: string): DiagramSlide | null {
  const [, , width, height] = (svg?.getAttribute("viewBox") ?? "").split(/[ ,]+/).map(Number)
  if (!svg || !width || !height) return null
  // 본문에서 폭에 맞추려고 붙인 크기(style)는 떼어, 창 안에서는 상자를 가득 채우게 한다.
  const copy = svg.cloneNode(true) as SVGSVGElement
  copy.removeAttribute("style")
  return { type: "diagram", svg: copy.outerHTML, width, height, label, background }
}

// 창 코드와 라이브러리는 처음 열 때 받는다.
const ZoomViewer = lazy(() => import("./ZoomViewer"))

/** 에디터마다 하나. 연 사진 · 도표는 크게 보기 창에, HTML 파일은 창을 거의 채우는 대화상자에 띄운다. */
export function ZoomHost({ slide, page, onClose }: { slide: ZoomSlide | null; page: HtmlPage | null; onClose: () => void }) {
  return <>
    {slide ? <Suspense fallback={null}><ZoomViewer slide={slide} onClose={onClose} /></Suspense> : null}
    <HtmlViewer page={page} onClose={onClose} />
  </>
}

/** 올린 HTML을 그리는 격리 틀의 권한: 스크립트 · 대화 · 양식 · 새 창은 되지만 같은 출처 권한이 없어 앱의 화면 · 쿠키 · 저장소에 닿지 못한다. */
export const HTML_SANDBOX = "allow-scripts allow-modals allow-forms allow-popups"

/**
 * 본문에 넣은 HTML 파일을 창 가득 크게 보는 창. 올린 사람의 스크립트가 들어 있을 수 있으므로 본문의 미리보기와 같은 격리된
 * 틀(sandbox) 안에서만 그린다. Esc와 닫기로 닫고, 초점 가두기는 대화상자가 맡는다. 틀의 바탕은 흰색으로 둔다(올린 HTML은
 * 대개 밝은 바탕을 전제로 하고, 바탕을 정하지 않은 문서가 어두운 화면에서 검은 글씨로 묻히지 않게).
 */
function HtmlViewer({ page, onClose }: { page: HtmlPage | null; onClose: () => void }) {
  // 저장 전의 임시 주소(blob:)는 새 탭에서 이 앱의 출처로 열리므로 내놓지 않는다. 서버가 내주는 주소는 서버가 격리 정책을 붙여 준다.
  const canOpenTab = !!page && !page.src.startsWith("blob:")
  return (
    <Dialog open={!!page} onOpenChange={next => { if (!next) onClose() }}>
      <DialogContent showCloseButton={false} aria-label={page ? `${page.title} 크게 보기` : undefined}
        className="flex h-[94dvh] w-[min(96vw,100rem)] max-w-none flex-col gap-0 overflow-hidden p-0 sm:max-w-none">
        <div className="flex flex-none items-center justify-between gap-2 border-b px-3 py-2">
          <DialogTitle className="min-w-0 truncate text-sm font-semibold">{page?.title}</DialogTitle>
          <div className="flex items-center gap-2">
            {canOpenTab ? <Button variant="secondary" size="sm" className="max-md:h-11" onClick={() => window.open(page.src, "_blank", "noopener,noreferrer")}>새 탭에서 열기</Button> : null}
            <Button variant="secondary" size="sm" className="max-md:h-11" onClick={onClose}>닫기</Button>
          </div>
        </div>
        {page ? <iframe src={page.src} title={page.title} sandbox={HTML_SANDBOX} referrerPolicy="no-referrer" className="block min-h-0 w-full flex-1 border-0 bg-white [color-scheme:light]" /> : null}
      </DialogContent>
    </Dialog>
  )
}

// 같은 주소의 카드는 한 번만 묻는다(본문을 다시 그려도, 같은 주소가 여러 번 나와도). 실패한 답은 다음에 다시 묻게 지운다.
const asked = new WeakMap<ReadLinkPreview, Map<string, Promise<LinkPreview>>>()
export function previewOf(read: ReadLinkPreview, url: string) {
  let known = asked.get(read)
  if (!known) { known = new Map(); asked.set(read, known) }
  let found = known.get(url)
  if (!found) { found = read(url); known.set(url, found); found.catch(() => known.delete(url)) }
  return found
}
